INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (253, N'FR-R38B-58', 14, N'LB ', N'CM ', N'LL Road Frame - Black, 58', N'Cuadro de carretera GB: negro, 58', N'Cadre de vélo de route LL - noir, 58', CAST(176.200000 AS Decimal(34, 6)), 1, N'Black', 500, 375, CAST(297.630000 AS Decimal(34, 6)), N'58', N'54-58 CM', 2.46, 1, N'R ', CAST(178.580000 AS Decimal(34, 6)), N'L ', N'U ', N'LL Road Frame', N'The LL Frame provides a safe comfortable ride, while offering superior bump absorption in a value-priced aluminum frame.', N'Le cadre LL en aluminium offre une conduite confortable, une excellente absorption des bosses pour un très bon rapport qualité-prix.', N'LL 车架提供了安全舒适的骑乘，经济实惠的铝制车架提供了卓越的避震功能。', N'يوفر الهيكل LL Frame قيادة آمنة ومريحة، مع توفير إمكانية فائقة لامتصاص الصدمات في هيكل من الألومنيوم جيد السعر بالنسبة لإمكاناته.', N'מסגרת ה- LL מספקת רכיבה בטוחה ונוחה ועם זאת, מציעה ספיגת חבטות מעולה של מסגרת אלומיניום במחיר סביר.', N'เฟรม LL ให้ความปลอดภัยและสบายขณะขับขี่ พร้อมทั้งซึมซับแรงกระแทก คุ้มราคาสำหรับเฟรมอลูมิเนียม', N'Mit dem LL-Rahmen fahren Sie sicher und komfortabel und profitieren von erstklassiger Stoßdämpfung in einem kostengünstigen Aluminiumrahmen.', N'LL フレームは、安全で快適に乗ることができ、値打ち価格のアルミニウム フレームで優れた衝撃吸収性を備えています。', N'"LL Kadro güvenli ve konforlu sürüş sunar, değerine uygun olarak fiyatlandırılan alüminyum kadrosu üstün çarpma şiddeti emişi sağlar."', CAST(N'2021-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2021-12-28T00:00:00.0000000' AS DateTime2), NULL)
