INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (321, N'BK-R50R-58', 2, N'LB ', N'CM ', N'Road-650 Red, 58', N'Carretera: 650, roja, 58', N'Vélo de route 650 rouge, 58', CAST(486.710000 AS Decimal(34, 6)), 1, N'Red', 100, 75, CAST(782.990000 AS Decimal(34, 6)), N'58', N'54-58 CM', 19.79, 4, N'R ', CAST(469.790000 AS Decimal(34, 6)), N'L ', N'U ', N'Road-650', N'Value-priced bike with many features of our top-of-the-line models. Has the same light, stiff frame, and the quick acceleration we''re famous for.', N'Vélo très séduisant comportant de nombreuses caractéristiques des modèles haut de gamme. Bénéficie du cadre léger et rigide, mais aussi de la ligne performante qui ont fait notre réputation.', N'此自行车经济实惠，具有我们的高档车型所拥有的许多功能。相同的车灯、刚架以及我们驰名业界的快速加速器。', N'إنها دراجة ذات سعر مناسب لإمكاناتها كما تتمتع بالعديد من مزايا أعلى طرازات دراجاتنا. إنها تتمتع أيضًا بما نشتهر به من هيكل خفيف وصلب، وسرعة في التسارع.', N'אופניים המהווים תמורה נאותה למחירם ובעלי רבות מתכונות דגמי הקו המוביל שלנו. מאופיינים במסגרת המוצקה והקלה וההאצה המהירה שבהם אנו מפורסמים.', N'จักรยานที่ให้ความคุ้มค่า ด้วยคุณสมบัติพิเศษมากมายจากรุ่นที่ดีที่สุด  พร้อมเฟรมที่เบา แกร่ง และอัตราเร่งที่สร้างชื่อเสียงให้กับเรา', N'"Kostengünstiges Rad mit vielen Funktionen unserer Topmodelle. Verfügt über denselben leichten, robusten Rahmen und die schnelle Beschleunigung, die uns bekannt gemacht hat."', N'最高級モデルの特色の多くを備えた値打ち価格の自転車です。ハイエンド クラスに匹敵する軽量高剛性フレームと、当社製品の特色である優れた加速性能を備えています。', N'Değerine uygun olarak fiyatlandırılan bisikletin bir çok özelliği en üst sınıf modellerinkilerle aynıdır. Aynı hafif sağlam kadroya ve herkesin takdir ettiği çabuk hızlanma özelliğimize sahiptir.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (323, N'BK-R50R-60', 2, N'LB ', N'CM ', N'Road-650 Red, 60', N'Carretera: 650, roja, 60', N'Vélo de route 650 rouge, 60', CAST(486.710000 AS Decimal(34, 6)), 1, N'Red', 100, 75, CAST(782.990000 AS Decimal(34, 6)), N'60', N'60-62 CM', 19.9, 4, N'R ', CAST(469.790000 AS Decimal(34, 6)), N'L ', N'U ', N'Road-650', N'Value-priced bike with many features of our top-of-the-line models. Has the same light, stiff frame, and the quick acceleration we''re famous for.', N'Vélo très séduisant comportant de nombreuses caractéristiques des modèles haut de gamme. Bénéficie du cadre léger et rigide, mais aussi de la ligne performante qui ont fait notre réputation.', N'此自行车经济实惠，具有我们的高档车型所拥有的许多功能。相同的车灯、刚架以及我们驰名业界的快速加速器。', N'إنها دراجة ذات سعر مناسب لإمكاناتها كما تتمتع بالعديد من مزايا أعلى طرازات دراجاتنا. إنها تتمتع أيضًا بما نشتهر به من هيكل خفيف وصلب، وسرعة في التسارع.', N'אופניים המהווים תמורה נאותה למחירם ובעלי רבות מתכונות דגמי הקו המוביל שלנו. מאופיינים במסגרת המוצקה והקלה וההאצה המהירה שבהם אנו מפורסמים.', N'จักรยานที่ให้ความคุ้มค่า ด้วยคุณสมบัติพิเศษมากมายจากรุ่นที่ดีที่สุด  พร้อมเฟรมที่เบา แกร่ง และอัตราเร่งที่สร้างชื่อเสียงให้กับเรา', N'"Kostengünstiges Rad mit vielen Funktionen unserer Topmodelle. Verfügt über denselben leichten, robusten Rahmen und die schnelle Beschleunigung, die uns bekannt gemacht hat."', N'最高級モデルの特色の多くを備えた値打ち価格の自転車です。ハイエンド クラスに匹敵する軽量高剛性フレームと、当社製品の特色である優れた加速性能を備えています。', N'Değerine uygun olarak fiyatlandırılan bisikletin bir çok özelliği en üst sınıf modellerinkilerle aynıdır. Aynı hafif sağlam kadroya ve herkesin takdir ettiği çabuk hızlanma özelliğimize sahiptir.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (546, N'PD-R563', 13, N'G  ', NULL, N'ML Road Pedal', N'Pedal de carretera GM', N'Pédale de vélo de route ML', CAST(27.570000 AS Decimal(34, 6)), 1, N'Silver/Black', 500, 375, CAST(62.090000 AS Decimal(34, 6)), NULL, N'NA', 168, 1, N'R ', CAST(37.250000 AS Decimal(34, 6)), N'M ', NULL, N'ML Road Pedal', N'Lightweight aluminum alloy construction.', N'Fabrication en alliage d''aluminium léger.', N'轻型铝合金结构。', N'تركيبة سبيكة ألومنيوم خفيفة الوزن.', N'מבנה סגסוגת אלומיניום קל משקל.', N'โครงสร้างอลูมิเนียมอัลลอยด์น้ำหนักเบา', N'Leichte Aluminiumlegierung.', N'軽量アルミニウム合金構造。', N'Hafif alüminyum alaşımı konstrüksiyon.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
