INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (236, N'LJ-0192-X', 21, NULL, NULL, N'Long-Sleeve Logo Jersey, XL', N'Jersey con logotipo de manga larga, SG', N'Maillot manches longues avec logo, taille XL', CAST(29.080000 AS Decimal(34, 6)), 1, N'Multi', 4, 3, CAST(48.070000 AS Decimal(34, 6)), N'XL', N'XL', NULL, 0, N'S ', CAST(28.840000 AS Decimal(34, 6)), NULL, N'U ', N'Long-Sleeve Logo Jersey', N'Unisex long-sleeve AWC logo microfiber cycling jersey', N'Maillot de cycliste en microfibre avec le logo de l''équipe AWV, manches longues, unisexe.', N'中性长袖带有 AWC 徽标的微纤维赛车用运动衫', N'قميص صوفي موحد للجنسين بأكمام طويلة للتسابق مصنوع من المايكروفيبر يحمل شعار AWC.', N'סריג לרכיבה, שרוול ארוך, יוניסקס, עשוי microfiber מתוצרת AWC.', N'เสื้อไมโครไฟเบอร์ติดโลโก้ AWC', N'Langärmliges Unisex-Microfiber-Trikot mit AWC-Logo', N'男女共用の、AWC ロゴ入り長袖マイクロファイバー サイクリング ジャージ。', N'"Üniseks uzun kollu, AWC logolu, mikro fiber bisiklet mayosu"', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
