INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (368, N'BK-R89R-44', 2, N'LB ', N'CM ', N'Road-250 Red, 44', N'Carretera: 250, roja, 44', N'Vélo de route 250 rouge, 44', CAST(1518.790000 AS Decimal(34, 6)), 1, N'Red', 100, 75, CAST(2443.350000 AS Decimal(34, 6)), N'44', N'42-46 CM', 14.77, 4, N'R ', CAST(1466.010000 AS Decimal(34, 6)), N'H ', N'U ', N'Road-250', N'Alluminum-alloy frame provides a light, stiff ride, whether you are racing in the velodrome or on a demanding club ride on country roads.', N'Cadre en alliage d''aluminium qui offre une conduite légère et rapide, sur pistes ou sur routes de campagne.', N'铝合金车架确保骑乘轻快、稳固，可用于室内比赛或参加俱乐部的越野活动。', N'يوفر الهيكل المصنوع من سبيكة ألومنيوم قيادة قوية وخفيفة الحركة في نفس الوقت، سواءً كنت تتسابق في حلبة سباق دراجات أو في سباق يتطلب مهارات خاصة ـ بأحد النوادي ـ داخل طرقات ريفية.', N'מסגרת מסגסוגת אלומיניום מספקת רכיבה קלה ומוצקה, בין אם במסלול מרוצים ובין אם ברכיבת מועדון תובענית בדרכים כפריות.', N'เฟรมอลูมิเนียมอัลลอยด์ ให้การขับขี่ที่เบา มั่นคง ไม่ว่าคุณจะแข่งอยู่ในเวโลโดรม หรือเผชิญกับเส้นทางที่ท้าทายเพียงใด', N'Der Rahmen aus Aluminiumlegierung bietet leichtes und stabiles Fahrvergnügen - ob im Velodrom oder auf Landstraßen.', N'レース トラックの走行でもオフロードのツーリングでも、アルミニウム合金のフレームにより、軽さと剛性を備えた乗り心地を提供します。', N'"Alüminyum alaşımı kadro, ister velodromda yarış yapın, ister köy yollarında zorlu takım sürüşlerine katılın hafif ve sağlam bir sürüş deneyimi sunar."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
