INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (222, N'HL-U509-B', 31, NULL, NULL, N'Sport-100 Helmet, Blue', N'Casco deportivo: 100, azul', N'Casque sport 100, bleu', CAST(13.090000 AS Decimal(34, 6)), 1, N'Blue', 4, 3, CAST(34.990000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'S ', CAST(20.990000 AS Decimal(34, 6)), NULL, NULL, N'Sport-100', N'Universal fit, well-vented, lightweight , snap-on visor.', N'Légère, aérée, taille unique, avec une visière amovible.', N'通用型透气良好且轻便，带有自合型帽沿。', N'ملائمة بشكل عام، وجيدة التهوية، وخفيفة الوزن بقناع واق من الشمس مزود بخاصية الالتصاق التلقائي.', N'מידה אונברסלית, מאווררת היטב, קלת-משקל, עם מצחייה מתחברת.', N'แว่นกันลมขนาดสากล ระบายอากาศได้ดี น้ำหนักเบา', N'"Einheitsgröße, atmungsaktiv, leicht, aufsetzbarer Blendschutz."', N'軽量で通気性に優れたユニバーサル フィットのスナップ オン バイザー。', N'"Her bisiklete kolayca takılabilen, aerodinamik, hafif dikiz aynası."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (416, N'FW-T905', 17, NULL, NULL, N'Touring Front Wheel', N'Rueda de paseo delantera', N'Roue avant de vélo de randonnée', CAST(96.800000 AS Decimal(34, 6)), 1, N'Black', 500, 375, CAST(218.010000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'T ', CAST(130.810000 AS Decimal(34, 6)), NULL, NULL, N'Touring Front Wheel', N'Aerodynamic rims for smooth riding.', N'Jantes aérodynamiques pour conduite en souplesse.', N'轮缘的设计符合空气动力学，确保平稳骑乘。', N'توفر خاصية الديناميكية الهوائية للإطارين المعدنيين قيادة سلسة.', N'חישוקים אווירודינמיים לרכיבה חלקה.', N'ขอบล้อแอโรไดนามิคสำหรับการขับขี่อย่างนุ่มนวล', N'Aerodynamische Felgen für ein geschmeidiges Fahrerlebnis.', N'滑らかな乗り心地を約束する空気力学的なリム。', N'Akıcı sürüş için aerodinamik jantlar.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (238, N'FR-R92R-62', 14, N'LB ', N'CM ', N'HL Road Frame - Red, 62', N'Cuadro de carretera GA: rojo, 62', N'Cadre de vélo de route HL - rouge, 62', CAST(747.970000 AS Decimal(34, 6)), 1, N'Red', 500, 375, CAST(1263.460000 AS Decimal(34, 6)), N'62', N'60-62 CM', 2.3, 1, N'R ', CAST(758.080000 AS Decimal(34, 6)), N'H ', N'U ', N'HL Road Frame', N'Our lightest and best quality aluminum frame made from the newest alloy; it is welded and heat-treated for strength. Our innovative design results in maximum comfort and performance.', N'Notre cadre en aluminium plus léger et de qualité supérieure fabriqué à partir du tout dernier alliage ; cadre soudé et traité à chaud pour une meilleure résistance. Le résultat d''une conception innovante pour un confort et des performances maximum.', N'重量最轻、质量最好的铝制车架采用最新的合金材质；经过焊接和热处理，坚固牢靠。我们创新的设计确保了最大程度的舒适和卓越的性能。', N'لقد تم صناعة هيكل دراجتنا الألومنيوم الأخف وزنًا والأعلى جودة، من أحدث السبائك المتوفرة، وتم لحامه ومعالجته حراريًا لزيادة قوته. ويوفر تصميمنا الإبداعي أقصى درجات الراحة والأداء.', N'מסגרת האלומיניום הקלה והאיכותית ביותר שלנו עשויה מהסגסוגת החדישה ביותר; להענקת חוזק, היא מרותכת ומוקשחת בחום. העיצוב החדשני שלנו בא לידי ביטוי בנוחות ובביצועים מרביים.', N'เฟรมอลูมิเนียมคุณภาพสูงสุดและน้ำหนักเบาที่สุด สร้างจากอัลลอยด์ชนิดใหม่ ได้รับการหลอมและให้ความร้อนเพื่อความแกร่ง  ด้วยนวัตกรรมการออกแบบ ทำให้มีความสบายและประสิทธิภาพสูงในเวลาเดียวกัน', N'Unser leichtester und hochwertigster Aluminiumrahmen aus der neuesten Legierung; geschweißt und hitzebehandelt für noch mehr Stabilität. Unser innovatives Design bietet maximalen Komfort und maximale Leistung.', N'最新の合金で作られた最軽量/最高品質のアルミニウム フレームで、強度を得るために溶接および熱処理されています。革新的なデザインにより、最高の快適さと性能がもたらされます。', N'"En yeni alaşımdan imal edilme, en hafif ve en kaliteli alüminyum kadromuz, daha güçlü olması için kaynaklandı ve tavlandı. Yenilikçi tasarımımız maksimum konfor ve performans sunar."', CAST(N'2021-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2021-12-28T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (241, N'FR-R92R-44', 14, N'LB ', N'CM ', N'HL Road Frame - Red, 44', N'Cuadro de carretera GA: rojo, 44', N'Cadre de vélo de route HL - rouge, 44', CAST(747.970000 AS Decimal(34, 6)), 1, N'Red', 500, 375, CAST(1263.460000 AS Decimal(34, 6)), N'44', N'42-46 CM', 2.12, 1, N'R ', CAST(758.080000 AS Decimal(34, 6)), N'H ', N'U ', N'HL Road Frame', N'Our lightest and best quality aluminum frame made from the newest alloy; it is welded and heat-treated for strength. Our innovative design results in maximum comfort and performance.', N'Notre cadre en aluminium plus léger et de qualité supérieure fabriqué à partir du tout dernier alliage ; cadre soudé et traité à chaud pour une meilleure résistance. Le résultat d''une conception innovante pour un confort et des performances maximum.', N'重量最轻、质量最好的铝制车架采用最新的合金材质；经过焊接和热处理，坚固牢靠。我们创新的设计确保了最大程度的舒适和卓越的性能。', N'لقد تم صناعة هيكل دراجتنا الألومنيوم الأخف وزنًا والأعلى جودة، من أحدث السبائك المتوفرة، وتم لحامه ومعالجته حراريًا لزيادة قوته. ويوفر تصميمنا الإبداعي أقصى درجات الراحة والأداء.', N'מסגרת האלומיניום הקלה והאיכותית ביותר שלנו עשויה מהסגסוגת החדישה ביותר; להענקת חוזק, היא מרותכת ומוקשחת בחום. העיצוב החדשני שלנו בא לידי ביטוי בנוחות ובביצועים מרביים.', N'เฟรมอลูมิเนียมคุณภาพสูงสุดและน้ำหนักเบาที่สุด สร้างจากอัลลอยด์ชนิดใหม่ ได้รับการหลอมและให้ความร้อนเพื่อความแกร่ง  ด้วยนวัตกรรมการออกแบบ ทำให้มีความสบายและประสิทธิภาพสูงในเวลาเดียวกัน', N'Unser leichtester und hochwertigster Aluminiumrahmen aus der neuesten Legierung; geschweißt und hitzebehandelt für noch mehr Stabilität. Unser innovatives Design bietet maximalen Komfort und maximale Leistung.', N'最新の合金で作られた最軽量/最高品質のアルミニウム フレームで、強度を得るために溶接および熱処理されています。革新的なデザインにより、最高の快適さと性能がもたらされます。', N'"En yeni alaşımdan imal edilme, en hafif ve en kaliteli alüminyum kadromuz, daha güçlü olması için kaynaklandı ve tavlandı. Yenilikçi tasarımımız maksimum konfor ve performans sunar."', CAST(N'2021-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2021-12-28T00:00:00.0000000' AS DateTime2), NULL)
