INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (425, N'RW-T905', 17, NULL, NULL, N'Touring Rear Wheel', N'Rueda de paseo trasera', N'Roue arrière de vélo de randonnée', CAST(108.780000 AS Decimal(34, 6)), 1, N'Black', 500, 375, CAST(245.010000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'T ', CAST(147.010000 AS Decimal(34, 6)), NULL, NULL, N'Touring Rear Wheel', N'Excellent aerodynamic rims guarantee a smooth ride.', N'Excellentes jantes aérodynamiques pour une conduite en souplesse.', N'出色的符合空气动力学的轮缘设计确保平稳骑乘。', N'إطاران معدنيان ممتازان يتميزان بخاصية الديناميكية الهوائية لضمان القيادة السلسلة.', N'חישוקים אווירודינמיים מצוינים מבטיחים רכיבה חלקה.', N'ขอบล้อแอโรไดนามิคสำหรับการขับขี่ที่นุ่มนวล', N'Hochwertige aerodynamische Felgen für ein komfortables Fahrerlebnis.', N'空気力学的に優れ、滑らかな乗り心地を保証するリム。', N'Mükemmel aerodinamik jantlar rahat bir sürüşü garanti eder.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
