INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (537, N'TI-M823', 37, NULL, NULL, N'HL Mountain Tire', N'Cubierta de montaña GA', N'Pneu de VTT HL', CAST(13.090000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(35.000000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'M ', CAST(21.000000 AS Decimal(34, 6)), N'H ', NULL, N'HL Mountain Tire', N'Incredible traction, lightweight carbon reinforced.', N'Traction exceptionnelle ; carbone léger renforcé.', N'惊人的牵引力；使用轻型碳纤维加强。', N'قوة جر هائلة، كربون مقوى خفيف الوزن.', N'אחיזת כביש שלא תאמן; חיזוק קל-משקל מפחמן.', N'เกาะถนนเหลือเชื่อ เสริมคาร์บอนน้ำหนักเบา', N'"Unvergleichliche Beschleunigung, leicht und carbonverstärkt."', N'優れたトラクションで、強化された軽量カーボン。', N'"İnanılmaz yol tutuşu, güçlendirilmiş hafif karbon."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (315, N'BK-R68R-58', 2, N'LB ', N'CM ', N'Road-450 Red, 58', N'Carretera: 450, roja, 58', N'Vélo de route 450 rouge, 58', CAST(884.710000 AS Decimal(34, 6)), 1, N'Red', 100, 75, CAST(1457.990000 AS Decimal(34, 6)), N'58', N'54-58 CM', 17.79, 4, N'R ', CAST(874.790000 AS Decimal(34, 6)), N'M ', N'U ', N'Road-450', N'A true multi-sport bike that offers streamlined riding and a revolutionary design. Aerodynamic design lets you ride with the pros, and the gearing will conquer hilly roads.', N'Un véritable vélo multi-sports, qui offre une conduite optimisée et une ligne révolutionnaire. Sa ligne aérodynamique vous permet de l''utiliser en course et ses vitesses de gravir les cols.', N'真正的多项运动自行车，骑乘自如，设计新颖。符合空气动力学的设计给您带来专业车手的体验，极佳的传动装置可以轻易征服陡峭的路面。', N'إنها دراجة تصلح للعديد من الرياضات وهي مصممة لتوفير أقصى فعالية للقيادة، كما تتميز بتصميم ابتكاري. يتيح لك تصميمها الديناميكي الهوائي إمكانية القيادة مع المحترفين، حيث إنها مزودة بتروس يمكنها الانطلاق داخل الطرق المرتفعة شديدة الانحدار.', N'אופניים שבאמת מתאימים לסוגי ספורט מרובים המציעים רכיבה חלקה ועיצוב מהפכני. עיצוב אווירודינמי מאפשר רכיבה עם מקצוענים ותשלובת גלגלי השיניים תתמודד עם כל דרך הררית.', N'จักรยานแข่งขันอเนกประสงค์ที่ให้การขับขี่ที่คล่องตัว และรูปลักษณ์ที่ไม่ซ้ำใคร  การออกแบบแอโรไดนามิค ช่วยให้คุณเทียบชั้นกับมืออาชีพ พร้อมกับระบบเกียร์ที่จะนำคุณทะยานเหนือเส้นทางบนภูเขาได้สบาย', N'Ein vielseitiges und windschnittiges Sportfahrrad mit einem revolutionären Design. Fahren Sie wie ein Profi mit dem aerodynamischen Design und der erstklassigen Gangschaltung für hügelige Strecken.', N'滑らかな乗り心地と革命的なデザインを提供する真のマルチスポーツ バイク。空気力学的なデザインにより、プロの乗り心地と、起伏の激しい道も克服するギアを提供します。', N'Akıcı sürüş ve çığır açıcı bir tasarım sunan gerçek bir çok amaçlı spor bisikleti. Aerodinamik tasarımı profesyonellerle sürmenize olanak verir ve vitesleri tepeleri fetheder.', CAST(N'2021-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2021-12-28T00:00:00.0000000' AS DateTime2), NULL)
