INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (493, N'FR-T67Y-62', 16, N'LB ', N'CM ', N'LL Touring Frame - Yellow, 62', N'Cuadro de paseo GB: amarillo, 62', N'Cadre de vélo de randonnée LL - jaune, 62', CAST(199.850000 AS Decimal(34, 6)), 1, N'Yellow', 500, 375, CAST(333.420000 AS Decimal(34, 6)), N'62', N'60-62 CM', 3.2, 1, N'T ', CAST(200.050000 AS Decimal(34, 6)), N'L ', N'U ', N'LL Touring Frame', N'Lightweight butted aluminum frame provides a more upright riding position for a trip around town.  Our ground-breaking design provides optimum comfort.', N'Cadre renforcé léger pour une position plus droite ; idéal pour les promenades en ville. Ligne remarquable pour un confort optimal.', N'轻型一体式铝制车架，可以更直立的骑乘姿势进行环城游。我们开创性的设计提供了最佳舒适度。', N'يوفر هيكل الألومنيوم سميك الأطراف خفيف الوزن وضع قيادة أكثر انتصابًا أثناء القيام برحلات في أرجاء البلدة. يوفر تصميمنا الابتكاري أعلى درجات الراحة.', N'מסגרת קלת משקל מאלומיניום חרוץ מספקת תנוחת רכיבה זקופה יותר לנסיעות בתוך העיר. העיצוב החדשני שלנו מספק נוחות מרבית.', N'เฟรมอลูมิเนียมน้ำหนักเบา ทำให้ท่วงท่าในการขับขี่ยืดตรง สำหรับทางเรียบ  ปฏิวัติการออกแบบเพื่อความสบายสูงสุด', N'Leichter Aluminiumrahmen für aufrechte Sitzhaltung bei Stadtfahrten. Unser bahnbrechendes Design bietet höchsten Komfort.', N'軽量接合アルミニウム フレームにより、街乗りに適したアップライトなライディング ポジションを実現します。当社の画期的なデザインより、最高の快適性を提供します。', N'"Hafif alüminyum kadrosu, şehirde yaptığınız yolculuklarda daha dik bir sürüş konumu sunuyor.  Çığır açıcı tasarımımız optimum konfor sağlıyor."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (502, N'FR-T67U-50', 16, N'LB ', N'CM ', N'LL Touring Frame - Blue, 50', N'Cuadro de paseo GB: azul, 50', N'Cadre de vélo de randonnée LL - bleu, 50', CAST(199.850000 AS Decimal(34, 6)), 1, N'Blue', 500, 375, CAST(333.420000 AS Decimal(34, 6)), N'50', N'48-52 CM', 3.1, 1, N'T ', CAST(200.050000 AS Decimal(34, 6)), N'L ', N'U ', N'LL Touring Frame', N'Lightweight butted aluminum frame provides a more upright riding position for a trip around town.  Our ground-breaking design provides optimum comfort.', N'Cadre renforcé léger pour une position plus droite ; idéal pour les promenades en ville. Ligne remarquable pour un confort optimal.', N'轻型一体式铝制车架，可以更直立的骑乘姿势进行环城游。我们开创性的设计提供了最佳舒适度。', N'يوفر هيكل الألومنيوم سميك الأطراف خفيف الوزن وضع قيادة أكثر انتصابًا أثناء القيام برحلات في أرجاء البلدة. يوفر تصميمنا الابتكاري أعلى درجات الراحة.', N'מסגרת קלת משקל מאלומיניום חרוץ מספקת תנוחת רכיבה זקופה יותר לנסיעות בתוך העיר. העיצוב החדשני שלנו מספק נוחות מרבית.', N'เฟรมอลูมิเนียมน้ำหนักเบา ทำให้ท่วงท่าในการขับขี่ยืดตรง สำหรับทางเรียบ  ปฏิวัติการออกแบบเพื่อความสบายสูงสุด', N'Leichter Aluminiumrahmen für aufrechte Sitzhaltung bei Stadtfahrten. Unser bahnbrechendes Design bietet höchsten Komfort.', N'軽量接合アルミニウム フレームにより、街乗りに適したアップライトなライディング ポジションを実現します。当社の画期的なデザインより、最高の快適性を提供します。', N'"Hafif alüminyum kadrosu, şehirde yaptığınız yolculuklarda daha dik bir sürüş konumu sunuyor.  Çığır açıcı tasarımımız optimum konfor sağlıyor."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (503, N'FR-T67U-54', 16, N'LB ', N'CM ', N'LL Touring Frame - Blue, 54', N'Cuadro de paseo GB: azul, 54', N'Cadre de vélo de randonnée LL - bleu, 54', CAST(199.850000 AS Decimal(34, 6)), 1, N'Blue', 500, 375, CAST(333.420000 AS Decimal(34, 6)), N'54', N'54-58 CM', 3.14, 1, N'T ', CAST(200.050000 AS Decimal(34, 6)), N'L ', N'U ', N'LL Touring Frame', N'Lightweight butted aluminum frame provides a more upright riding position for a trip around town.  Our ground-breaking design provides optimum comfort.', N'Cadre renforcé léger pour une position plus droite ; idéal pour les promenades en ville. Ligne remarquable pour un confort optimal.', N'轻型一体式铝制车架，可以更直立的骑乘姿势进行环城游。我们开创性的设计提供了最佳舒适度。', N'يوفر هيكل الألومنيوم سميك الأطراف خفيف الوزن وضع قيادة أكثر انتصابًا أثناء القيام برحلات في أرجاء البلدة. يوفر تصميمنا الابتكاري أعلى درجات الراحة.', N'מסגרת קלת משקל מאלומיניום חרוץ מספקת תנוחת רכיבה זקופה יותר לנסיעות בתוך העיר. העיצוב החדשני שלנו מספק נוחות מרבית.', N'เฟรมอลูมิเนียมน้ำหนักเบา ทำให้ท่วงท่าในการขับขี่ยืดตรง สำหรับทางเรียบ  ปฏิวัติการออกแบบเพื่อความสบายสูงสุด', N'Leichter Aluminiumrahmen für aufrechte Sitzhaltung bei Stadtfahrten. Unser bahnbrechendes Design bietet höchsten Komfort.', N'軽量接合アルミニウム フレームにより、街乗りに適したアップライトなライディング ポジションを実現します。当社の画期的なデザインより、最高の快適性を提供します。', N'"Hafif alüminyum kadrosu, şehirde yaptığınız yolculuklarda daha dik bir sürüş konumu sunuyor.  Çığır açıcı tasarımımız optimum konfor sağlıyor."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
