INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (538, N'TI-R092', 37, NULL, NULL, N'LL Road Tire', N'Cubierta de carretera GB', N'Pneu de vélo de route LL', CAST(8.040000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(21.490000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'R ', CAST(12.890000 AS Decimal(34, 6)), N'L ', NULL, N'LL Road Tire', N'Same great treads as more expensive tire with a less expensive wire bead casing.', N'Même dessin que les pneus plus chers, mais doté d''une gomme moins chère.', N'钢丝撑轮圈外胎的价格便宜，轮胎面却与价格更贵的轮胎同样出色。', N'السطح الخارجي للإطار بنفس جودة أسطح الإطارات الخارجية الأغلى ثمنًا، ولكنه مزود بغطاء حافة بارزة مطاطي أقل سعرًا.', N'חריצי צמיג זהים לאלה המצויים בצמיגים יקרים יותר, אולם עם יציקת תילי צמיג יקרה פחות.', N'ดอกยางชั้นยอดเช่นเดียวกับยางราคาแพง แต่ใช้โครงไวร์บีดราคาประหยัด', N'Dasselbe Profil wie ein teurerer Reifen mit kostengünstigerem Mantel.', N'低価格のワイヤ ビード ケーシングでハイエンド タイヤに匹敵する優れたトレッドを実現。', N'"Daha pahalı tekerleklerle aynı lastik sırtı, daha ucuz tel başları."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
