INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (123, N'LN-1428', NULL, NULL, NULL, N'Lock Nut 9', NULL, NULL, NULL, 0, N'NA', 1000, 750, NULL, NULL, N'NA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, CAST(N'2021-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (579, N'BK-T44U-54', 3, N'LB ', N'CM ', N'Touring-2000 Blue, 54', N'Paseo: 2000, azul, 54', N'Vélo de randonnée 2000 bleu, 54', CAST(755.150000 AS Decimal(34, 6)), 1, N'Blue', 100, 75, CAST(1214.850000 AS Decimal(34, 6)), N'54', N'54-58 CM', 27.68, 4, N'T ', CAST(728.910000 AS Decimal(34, 6)), N'M ', N'U ', N'Touring-2000', N'The plush custom saddle keeps you riding all day,  and there''s plenty of space to add panniers and bike bags to the newly-redesigned carrier.  This bike has stability when fully-loaded.', N'La selle rembourrée offre un confort optimal. Le porte-bagages nouvellement remanié offre diverses possibilités d''ajout de paniers ou de sacoches. Ce vélo reste parfaitement stable une fois chargé.', N'豪华的定制车座，确保您全天舒适骑乘，重新设计过的行李架上有足够的空间可添加驮篮和车筐。此自行车在完全负重情况下非常稳固。', N'إن مقعد الدراجة المخصص المصنوع من نسيج البلش يجعلك لا تمل أبدًا من القيادة طوال اليوم، كما يوفر لك حامل الدراجة بتصميمه المحدّث مساحة كبيرة تستوعب أكثر من سلة وشنطة على الدراجة. وتحتفظ هذه الدراجة بتوازنها حتى عند تحميلها بالكامل.', N'המושב המשובח והמותאם אישית מאפשר רכיבה לאורך היום כולו וקיים מקום רב להוספת תיקי אוכף ותיקי אופניים למנשא שעוצב מחדש. אופניים אלה שומרים על יציבות גם בעומס מלא.', N'เบาะนั่งหุ้มพิเศษช่วยให้คุณขี่อย่างสบายตลอดทั้งวัน ตะแกรงออกแบบใหม่ มีพื้นที่เหลือเฟือสำหรับตะกร้าและกระเป๋า ขับขี่อย่างมั่นคง แม้ขณะบรรทุกของ', N'"Der Polstersattel bietet Fahrkomfort für den ganzen Tag, und der Gepäckträger mit neuem Design bietet viel Platz für Fahrradtaschen und Körbe. Dieses Fahrrad behält seine Stabilität auch im voll beladenen Zustand."', N'プラッシュ カスタム サドルは 1 日中乗っていたくなる快適さです。新設計の荷台には、パニエやバイク バッグを追加するのに十分なスペースがあります。荷物を満載しても安定する自転車です。', N'"Özel yapım konforlu sele ile tüm gün bisiklet sürebilirsiniz, ayrıca kısa süre önce yeniden tasarlanan taşıyıcıda sepet ve bisiklet çantası eklenebilecek bol yer vardır.  Bu bisiklet tam olarak yüklendiğinde dengelidir."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (501, N'RD-2308', 9, N'G  ', NULL, N'Rear Derailleur', N'Desviador trasero', N'Dérailleur arrière', CAST(53.930000 AS Decimal(34, 6)), 1, N'Silver', 500, 375, CAST(121.460000 AS Decimal(34, 6)), NULL, N'NA', 215, 1, NULL, CAST(72.880000 AS Decimal(34, 6)), NULL, NULL, N'Rear Derailleur', N'Wide-link design.', N'Conception liaison large.', N'宽连杆设计。', N'تصميم عريض الوصلات.', N'עיצוב רחב-חוליות.', N'การออกแบบให้มีจุดเชื่อมกว้าง', N'Wide-Link-Design.', N'ワイドリンク デザイン。', N'Geniş bağlantılı tasarım.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (514, N'RB-9231', 6, N'G  ', NULL, N'Rear Brakes', N'Frenos traseros', N'Freins arrière', CAST(47.290000 AS Decimal(34, 6)), 1, N'Silver', 500, 375, CAST(106.500000 AS Decimal(34, 6)), NULL, N'NA', 317, 1, NULL, CAST(63.900000 AS Decimal(34, 6)), NULL, NULL, N'Rear Brakes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (542, N'PD-M282', 13, N'G  ', NULL, N'LL Mountain Pedal', N'Pedal de montaña GB', N'Pédale de VTT LL', CAST(17.980000 AS Decimal(34, 6)), 1, N'Silver/Black', 500, 375, CAST(40.490000 AS Decimal(34, 6)), NULL, N'NA', 218, 1, N'M ', CAST(24.290000 AS Decimal(34, 6)), N'L ', NULL, N'LL Mountain Pedal', N'Expanded platform so you can ride in any shoes; great for all-around riding.', N'Plate-forme allongée permettant de rouler avec tous types de chaussures ; idéal pour la randonnée.', N'展开式踏板便于您穿任何鞋子骑乘；适用于各种情况。', N'هيكل أساسي واسع بحيث يمكنك القيادة بأي حذاء، وهذا أمر رائع للقيادة متعددة الأغراض.', N'משטח דוושות מורחב המתאים לרכיבה בכל סוגי הנעלים; מצוין לרכיבה לכל מטרה.', N'คันถีบขนาดใหญ่ สำหรับการขับขี่ด้วยรองเท้าชนิดใดก็ได้ เหมาะสำหรับการขับขี่อเนกประสงค์', N'Größere Fläche für Komfort in allen Schuhen.', N'靴を選ばない拡張プラットフォームなので、オールラウンド ライディングに最適です。', N'"Geniş pedalı sayesinde her tür ayakkabıyla sürebilirsiniz, günlük kullanım için çok uygundur."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (543, N'PD-M340', 13, N'G  ', NULL, N'ML Mountain Pedal', N'Pedal de montaña GM', N'Pédale de VTT ML', CAST(27.570000 AS Decimal(34, 6)), 1, N'Silver/Black', 500, 375, CAST(62.090000 AS Decimal(34, 6)), NULL, N'NA', 215, 1, N'M ', CAST(37.250000 AS Decimal(34, 6)), N'M ', NULL, N'ML Mountain Pedal', N'Lightweight, durable, clipless pedal with adjustable tension.', N'Pédales automatiques légères et robustes avec tension réglable.', N'无扣带式脚踏轻型耐用且松紧可调。', N'دواسة خفيفة الوزن شديدة التحمّل بلا مشابك وذات قوة شدّ يمكن تعديلها.', N'דוושה עמידה נטולת חבקים עם מאמץ מתכוונן.', N'คันถีบน้ำหนักเบา ทนทาน ไม่มีคลิป และสามารถปรับความตึงได้', N'Leichte Pedale ohne Pedalhaken mit anpassbarer Spannung.', N'軽量で耐久性に優れ、テンション調整が可能なクリップレス ペダル。', N'"Hafif, dayanıklı klipssiz pedal, gerginliği ayarlanabilir."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (555, N'FB-9873', 6, N'G  ', NULL, N'Front Brakes', N'Frenos delanteros', N'Freins avant', CAST(47.290000 AS Decimal(34, 6)), 1, N'Silver', 500, 375, CAST(106.500000 AS Decimal(34, 6)), NULL, N'NA', 317, 1, NULL, CAST(63.900000 AS Decimal(34, 6)), NULL, NULL, N'Front Brakes', N'All-weather brake pads; provides superior stopping by applying more surface to the rim.', N'Patins de freinage pour tous les temps ; freinage renforcé par l''application d''une plus grande surface sur la jante.', N'全天候刹车垫；通过增加与轮缘的接触面积来提供优异的制动功能。', N'تحتوي على بطانات (تيل) فرامل، تناسب كافة الظروف الجوية، مما يتيح إمكانية إيقاف فائقة وذلك بتطبيق مساحة أكبر من سطح الفرامل على الإطار المعدني.', N'רפידות מעצור המתאימות לכל מזג אוויר; מספקות עצירה מעולה על-ידי החלת יותר שטח לחישוק.', N'ยางเบรกสำหรับทุกสภาพอากาศ เพื่อการหยุดที่มั่นใจ ด้วยหน้าสัมผัสกับขอบล้อมากกว่า', N'Allwetter-Bremsbeläge für erstklassiges Bremsen durch mehr Reibung auf der Felge.', N'全天候型ブレーキ パッドを採用し、リムに広い表面積を適用することにより優れた制動力を提供します。', N'"Tüm hava durumlarına uygun fren pedleri, jantın daha büyük bir yüzeyine uygulanarak çok güçlü durdurma sağlar."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (556, N'CS-4759', 8, N'G  ', NULL, N'LL Crankset', N'Bielas GB', N'Pédalier LL', CAST(77.920000 AS Decimal(34, 6)), 1, N'Black', 500, 375, CAST(175.490000 AS Decimal(34, 6)), NULL, N'NA', 600, 1, NULL, CAST(105.290000 AS Decimal(34, 6)), N'L ', NULL, N'LL Crankset', N'Super rigid spindle.', N'Axe très rigide.', N'极其坚实的脚踏轴。', N'محور دوران صلب فائق الأداء.', N'ציר קשיח במיוחד.', N'เพลาล้อสุดแกร่ง', N'Extrem robuste Achse.', N'最強の剛性を誇るスピンドル。', N'Çok sağlam mil.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (557, N'CS-6583', 8, N'G  ', NULL, N'ML Crankset', N'Bielas GM', N'Pédalier ML', CAST(113.880000 AS Decimal(34, 6)), 1, N'Black', 500, 375, CAST(256.490000 AS Decimal(34, 6)), NULL, N'NA', 635, 1, NULL, CAST(153.890000 AS Decimal(34, 6)), N'M ', NULL, N'ML Crankset', N'High-strength crank arm.', N'Manivelle haute résistance.', N'高强度的曲臂。', N'ذراع تدوير شديد القوة.', N'זרוע ארכובה עתירת עוצמה.', N'คันบังคับแข็งแรงเป็นพิเศษ', N'Robuster Pedalarm.', N'高強度クランク アーム。', N'Çok güçlü krank kolu.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (558, N'CS-9183', 8, N'G  ', NULL, N'HL Crankset', N'Bielas GA', N'Pédalier HL', CAST(179.820000 AS Decimal(34, 6)), 1, N'Black', 500, 375, CAST(404.990000 AS Decimal(34, 6)), NULL, N'NA', 575, 1, NULL, CAST(242.990000 AS Decimal(34, 6)), N'H ', NULL, N'HL Crankset', N'Triple crankset; alumunim crank arm; flawless shifting.', N'Pédalier triple plateaux ; manivelle en aluminium ; changement de braquet impeccable.', N'三重齿盘；铝制曲臂；完美变速。', N'مجموعة تدوير ثلاثية، وذراع تدوير ألومنيوم، وإمكانية نقل سرعات دون حدوث أخطاء.', N'ערכת ארכובה משולשת, זרוע ארכובה מאלומיניום, חילוף הילוכים מושלם.', N'ชุดควบคุมสามชั้น คันบังคับอลูมิเนียม และการเปลี่ยนเกียร์ที่สมบูรณ์แบบ', N'Dreifach-Kurbelsatz; Aluminium-Pedalarm; tadellose Gangschaltung.', N'トリプル クランクセット、アルミニウム クランク アーム、完璧なシフト。', N'"Üçlü ruble, alüminyum krank kolu, takılmadan vites geçişi."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (601, N'BB-7421', 5, N'G  ', NULL, N'LL Bottom Bracket', N'Eje de pedalier GB', N'Axe de pédalier LL', CAST(23.970000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(53.990000 AS Decimal(34, 6)), NULL, N'NA', 223, 1, NULL, CAST(32.390000 AS Decimal(34, 6)), N'L ', NULL, N'LL Bottom Bracket', N'Chromoly steel.', N'Acier chromé.', N'铬钢。', N'الفولاذ الكرومولي', N'פלדת כרומולי (כרום-מולובדניום)', N'โลหะโครโมลี', N'Chromstahl.', N'クロム鋼。', N'Kromoli çelik.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
