INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (381, N'BK-R64Y-38', 2, N'LB ', N'CM ', N'Road-550-W Yellow, 38', N'Carretera: 550 para mujer, amarilla, 38', N'Vélo de route 550 -W - jaune, 38', CAST(605.650000 AS Decimal(34, 6)), 1, N'Yellow', 100, 75, CAST(1000.440000 AS Decimal(34, 6)), N'38', N'38-40 CM', 17.35, 4, N'R ', CAST(600.260000 AS Decimal(34, 6)), N'M ', N'W ', N'Road-550-W', N'Same technology as all of our Road series bikes, but the frame is sized for a woman.  Perfect all-around bike for road or racing.', N'Équipé de la même technologie que tous nos vélos de route, avec un cadre femmes. Idéal pour la promenade ou la course sur route.', N'使用的技术与我们所有的公路系列自行车完全相同，但车架尺寸专为女士设计。完美的全能自行车，可作一般用途也可参加比赛。', N'ولها نفس التقنية المتوفرة في جميع دراجات سلسلة الطريق لدينا، ولكن هيكل الدراجة قد تم تغيير حجمه ليناسب القيادة النسائية. إنها دراجة مثالية تصلح للعديد من الأغراض، وتناسب القيادة على الطرق العادية أو القيادة في السباقات.', N'טכנולוגיה זהה לזו המצוי באופני סדרת "כביש" שלנו, אולם המסגרת בגודל המותאם לנשים. מושלמים כאופניים לכל מטרה לכביש ולתחרויות.', N'เทคโนโลยีเดียวกับจักรยานรุ่น Road ทั้งหมด แต่ใช้เฟรมขนาดกะทัดรัดสำหรับสุภาพสตรี  เหมาะสำหรับการขับขี่อเนกประสงค์ ไม่ว่าจะเป็นท้องถนนทั่วไปหรือการแข่งขัน', N'Dieselbe Technologie wie bei allen Rädern unserer Road-Produktreihe mit Frauenrahmen. Perfektes Allzweckrad zum Trainieren und für den Alltag.', N'ロード シリーズの自転車と同じ技術を使用した女性用サイズのフレームで、ロードにも競技にも適した汎用自転車です。', N'"Yol serisi bisikletlerimizle aynı teknoloji, ancak kadro boyutu kadınlar için ayarlandı.  Yol ve yarış için mükemmel çok yönlü bisiklet."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (382, N'BK-R64Y-38', 2, N'LB ', N'CM ', N'Road-550-W Yellow, 38', N'Carretera: 550 para mujer, amarilla, 38', N'Vélo de route 550 -W - jaune, 38', CAST(713.080000 AS Decimal(34, 6)), 1, N'Yellow', 100, 75, CAST(1120.490000 AS Decimal(34, 6)), N'38', N'38-40 CM', 17.35, 4, N'R ', CAST(672.290000 AS Decimal(34, 6)), N'M ', N'W ', N'Road-550-W', N'Same technology as all of our Road series bikes, but the frame is sized for a woman.  Perfect all-around bike for road or racing.', N'Équipé de la même technologie que tous nos vélos de route, avec un cadre femmes. Idéal pour la promenade ou la course sur route.', N'使用的技术与我们所有的公路系列自行车完全相同，但车架尺寸专为女士设计。完美的全能自行车，可作一般用途也可参加比赛。', N'ولها نفس التقنية المتوفرة في جميع دراجات سلسلة الطريق لدينا، ولكن هيكل الدراجة قد تم تغيير حجمه ليناسب القيادة النسائية. إنها دراجة مثالية تصلح للعديد من الأغراض، وتناسب القيادة على الطرق العادية أو القيادة في السباقات.', N'טכנולוגיה זהה לזו המצוי באופני סדרת "כביש" שלנו, אולם המסגרת בגודל המותאם לנשים. מושלמים כאופניים לכל מטרה לכביש ולתחרויות.', N'เทคโนโลยีเดียวกับจักรยานรุ่น Road ทั้งหมด แต่ใช้เฟรมขนาดกะทัดรัดสำหรับสุภาพสตรี  เหมาะสำหรับการขับขี่อเนกประสงค์ ไม่ว่าจะเป็นท้องถนนทั่วไปหรือการแข่งขัน', N'Dieselbe Technologie wie bei allen Rädern unserer Road-Produktreihe mit Frauenrahmen. Perfektes Allzweckrad zum Trainieren und für den Alltag.', N'ロード シリーズの自転車と同じ技術を使用した女性用サイズのフレームで、ロードにも競技にも適した汎用自転車です。', N'"Yol serisi bisikletlerimizle aynı teknoloji, ancak kadro boyutu kadınlar için ayarlandı.  Yol ve yarış için mükemmel çok yönlü bisiklet."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (227, N'LJ-0192-S', 21, NULL, NULL, N'Long-Sleeve Logo Jersey, S', N'Jersey con logotipo de manga larga, P', N'Maillot manches longues avec logo, taille S', CAST(29.080000 AS Decimal(34, 6)), 1, N'Multi', 4, 3, CAST(48.070000 AS Decimal(34, 6)), N'S', N'S', NULL, 0, N'S ', CAST(28.840000 AS Decimal(34, 6)), NULL, N'U ', N'Long-Sleeve Logo Jersey', N'Unisex long-sleeve AWC logo microfiber cycling jersey', N'Maillot de cycliste en microfibre avec le logo de l''équipe AWV, manches longues, unisexe.', N'中性长袖带有 AWC 徽标的微纤维赛车用运动衫', N'قميص صوفي موحد للجنسين بأكمام طويلة للتسابق مصنوع من المايكروفيبر يحمل شعار AWC.', N'סריג לרכיבה, שרוול ארוך, יוניסקס, עשוי microfiber מתוצרת AWC.', N'เสื้อไมโครไฟเบอร์ติดโลโก้ AWC', N'Langärmliges Unisex-Microfiber-Trikot mit AWC-Logo', N'男女共用の、AWC ロゴ入り長袖マイクロファイバー サイクリング ジャージ。', N'"Üniseks uzun kollu, AWC logolu, mikro fiber bisiklet mayosu"', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
