INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (216, N'HL-U509', 31, NULL, NULL, N'Sport-100 Helmet, Black', N'Casco deportivo: 100, negro', N'Casque sport 100, noir', CAST(13.880000 AS Decimal(34, 6)), 1, N'Black', 4, 3, CAST(33.640000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'S ', CAST(20.190000 AS Decimal(34, 6)), NULL, NULL, N'Sport-100', N'Universal fit, well-vented, lightweight , snap-on visor.', N'Légère, aérée, taille unique, avec une visière amovible.', N'通用型透气良好且轻便，带有自合型帽沿。', N'ملائمة بشكل عام، وجيدة التهوية، وخفيفة الوزن بقناع واق من الشمس مزود بخاصية الالتصاق التلقائي.', N'מידה אונברסלית, מאווררת היטב, קלת-משקל, עם מצחייה מתחברת.', N'แว่นกันลมขนาดสากล ระบายอากาศได้ดี น้ำหนักเบา', N'"Einheitsgröße, atmungsaktiv, leicht, aufsetzbarer Blendschutz."', N'軽量で通気性に優れたユニバーサル フィットのスナップ オン バイザー。', N'"Her bisiklete kolayca takılabilen, aerodinamik, hafif dikiz aynası."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
