INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (488, N'SJ-0194-S', 21, NULL, NULL, N'Short-Sleeve Classic Jersey, S', N'Jersey clásico de manga corta, P', N'Maillot manches courtes classique, taille S', CAST(41.570000 AS Decimal(34, 6)), 1, N'Yellow', 4, 3, CAST(53.990000 AS Decimal(34, 6)), N'S', N'S', NULL, 0, N'S ', CAST(32.390000 AS Decimal(34, 6)), NULL, N'U ', N'Short-Sleeve Classic Jersey', N'Short sleeve classic breathable jersey with superior moisture control, front zipper, and 3 back pockets.', N'Maillot manches courtes classique et anti-transpiration avec contrôle de l''humidité, fermeture avant à glissière et 3 poches arrière.', N'短袖、式样经典的透气型运动衫，极佳的湿度控制、前拉练并带有三个后袋。', N'قميص صوفي قصير الأكمام كلاسيكي يسمح بمرور الهواء خلاله مع تحكم فائق في الرطوبة، مزود بزمام منزلق أمامي، وثلاثة جيوب خلفية.', N'סריג קלאסי,נושם, שרוול קצר, עם בקרת לחות מעולה, רוכסן קדמי ושלושה כיסי גב.', N'เสื้อแขนสั้นแบบคลาสสิค ระบายอากาศได้ดี ควบคุมความชื้น ซิปหน้า พร้อมกระเป๋าหลัง 3 ใบ', N'"Klassisches, atmungsaktives Trikot mit hochwertiger Feuchtigkeitsableitung, Reißverschluss und drei Rückentaschen."', N'優れた湿度調整機能、前面ジッパー、および後ろポケット 3 つが付いた、通気性に富むクラシックな半袖ジャージ。', N'"Üstün nem kontrollü, önden fermuarlı ve üç arka cepli kısa kollu hava alan mayo."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
