INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (445, N'SH-M897-S', 22, NULL, NULL, N'Men''s Sports Shorts, S', N'Pantalones cortos de deporte para hombre, P', N'Cuissards de route pour hommes, taille S', CAST(24.750000 AS Decimal(34, 6)), 1, N'Black', 4, 3, CAST(59.990000 AS Decimal(34, 6)), N'S', N'S', NULL, 0, N'S ', CAST(35.990000 AS Decimal(34, 6)), NULL, N'M ', N'Men''s Sports Shorts', N'Men''s 8-panel racing shorts - lycra with an elastic waistband and leg grippers.', N'Cuissards de course pour hommes - en Spandex avec un élastique à la ceinture et bande anti-remontée.', N'男士八拼片竞赛用运动短裤 – 氨纶材质、弹性腰带并带腿夹。', N'قمصان سباق رجالي ذات ثمانية أقسام، من قماش سباندكس وذات حزام مرن وماسكات للرجلين.', N'מכנסי גברים קצרים לתחרויות, 8 חלקים – עשויים ספנדקס עם חגורה אלסטית והידוק רגליים.', N'กางเกงแข่ง 8 ช่องสำหรับสุภาพบุรุษ - เส้นใยสแปนเด็กซ์พร้อมยางยืดและที่รัดขา', N'Rennradhose für Herren - Lycra mit elastischem Bund und Beinabschluss ohne Verrutschen.', N'男性用 8 枚剥ぎの競技用ショーツ - 伸縮性のあるウエスト バンドとレッグ グリッパー付きのライクラ製です。', N'Erkekler için 8 parçalı yarış şortu - elastik kemer parçalı ve bacak tutuculu likra.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
