INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (456, N'TG-W091-S', 24, NULL, NULL, N'Women''s Tights, S', N'Mallas para mujer, P', N'Collants pour femmes, taille S', CAST(30.930000 AS Decimal(34, 6)), 1, N'Black', 4, 3, CAST(74.990000 AS Decimal(34, 6)), N'S', N'S', NULL, 0, N'S ', CAST(44.990000 AS Decimal(34, 6)), NULL, N'W ', N'Women''s Tights', N'Warm spandex tights for winter riding; seamless chamois construction eliminates pressure points.', N'Collants chauds en Spandex pour l''hiver ; fabrication en chamoisine sans couture pour éliminer les points de frottement.', N'保暖型氨纶紧身运动衣适用于冬季骑乘；无缝麂皮结构可化解压力。', N'تساعد الرداءات المحكمة المصنوعة من الاسباندكس المخصصة للقيادة في فصل الشتاء، مع تركيبة الشمواة الانسيابية على التخلص من مواضع الضغط.', N'מכנסי ספנדקס צמודים וחמים לרכיבה חורפית; עור רך נטול תפרים מפחית מנקודות הלחיצה.', N'กางเกงสแปนเด็กซ์ให้ความอบอุ่นในการขับขี่หน้าหนาว บุชามัวส์ไร้ตะเข็บสำหรับจุดกดทับ', N'Warme Spandex-Radlerhose für den Winter; mit nahtloser Lederpolsterung zur Vermeidung von Druckstellen.', N'冬用の暖かいスパンデックス タイツで、縫い目ストレスのないシームレスのシャモア構造です。', N'"Kış sürüşleri için sıcak spandeks taytlar, basınç yapan noktaları etkisiz hale getiren dikişsiz ped."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
