INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (30, N'FW-9160', NULL, NULL, NULL, N'Flat Washer 7', NULL, NULL, NULL, 0, N'NA', 1000, 750, NULL, NULL, N'NA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, CAST(N'2021-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (468, N'GL-F110-S', 20, NULL, NULL, N'Full-Finger Gloves, S', N'Guantes completos, P', N'Gants longs, taille S', CAST(15.670000 AS Decimal(34, 6)), 1, N'Black', 4, 3, CAST(37.990000 AS Decimal(34, 6)), N'S', N'S', NULL, 0, N'M ', CAST(22.790000 AS Decimal(34, 6)), NULL, N'U ', N'Full-Finger Gloves', N'Synthetic palm, flexible knuckles, breathable mesh upper. Worn by the AWC team riders.', N'Paume synthétique, poignets souples, ouverture maillée anti-transpiration. Adopté par les professionnels de l''équipe AWC.', N'合成材质手掌、灵活的指关节、上部带有透气型网眼。AWC车队赛手专用。', N'قفاز ذو راحة يد صناعية، ومفاصل أصابع مرنة، وفتحات علوية تسمح بمرور الهواء. يرتديه راكبو دراجات فريق AWC.', N'אזור כף יד מחומר סינטטי, מפרקים גמישים, רשת נושמת בחלק העליון. נלבש על-ידי רוכבי קבוצת AWC.', N'แผ่นฝ่ามือสังเคราะห์ ข้อนิ้วยืดหยุ่น และตาข่ายส่วนบนช่วยระบายอากาศ  ได้รับความไว้วางใจจากนักแข่งทีม AWC', N'"Ballenschutz Synthetik, flexible Fingerpartie, atmungsaktives Netz am Handrücken. Wird von den Fahrern des AWC-Teams getragen."', N'シンセティック レザーの手のひら部分、柔軟性のある関節部分、通気性のあるメッシュの甲部分。AWC チームのライダーも愛用しています。', N'"Sentetik avuç içi, esnek parmaklar, üst tarafı hava alan ağdan imal edilmiştir. AWC takımı sürücüleri tarafından takılmaktadır."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (469, N'GL-F110-M', 20, NULL, NULL, N'Full-Finger Gloves, M', N'Guantes completos, M', N'Gants longs, taille M', CAST(15.670000 AS Decimal(34, 6)), 1, N'Black', 4, 3, CAST(37.990000 AS Decimal(34, 6)), N'M', N'M', NULL, 0, N'M ', CAST(22.790000 AS Decimal(34, 6)), NULL, N'U ', N'Full-Finger Gloves', N'Synthetic palm, flexible knuckles, breathable mesh upper. Worn by the AWC team riders.', N'Paume synthétique, poignets souples, ouverture maillée anti-transpiration. Adopté par les professionnels de l''équipe AWC.', N'合成材质手掌、灵活的指关节、上部带有透气型网眼。AWC车队赛手专用。', N'قفاز ذو راحة يد صناعية، ومفاصل أصابع مرنة، وفتحات علوية تسمح بمرور الهواء. يرتديه راكبو دراجات فريق AWC.', N'אזור כף יד מחומר סינטטי, מפרקים גמישים, רשת נושמת בחלק העליון. נלבש על-ידי רוכבי קבוצת AWC.', N'แผ่นฝ่ามือสังเคราะห์ ข้อนิ้วยืดหยุ่น และตาข่ายส่วนบนช่วยระบายอากาศ  ได้รับความไว้วางใจจากนักแข่งทีม AWC', N'"Ballenschutz Synthetik, flexible Fingerpartie, atmungsaktives Netz am Handrücken. Wird von den Fahrern des AWC-Teams getragen."', N'シンセティック レザーの手のひら部分、柔軟性のある関節部分、通気性のあるメッシュの甲部分。AWC チームのライダーも愛用しています。', N'"Sentetik avuç içi, esnek parmaklar, üst tarafı hava alan ağdan imal edilmiştir. AWC takımı sürücüleri tarafından takılmaktadır."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
