INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (218, N'SO-B909-M', 23, NULL, NULL, N'Mountain Bike Socks, M', N'Calcetines para bicicleta de montaña, M', N'Chaussettes de VTT, taille M', CAST(3.400000 AS Decimal(34, 6)), 1, N'White', 4, 3, CAST(9.500000 AS Decimal(34, 6)), N'M', N'M', NULL, 0, N'M ', CAST(5.700000 AS Decimal(34, 6)), NULL, N'U ', N'Mountain Bike Socks', N'Combination of natural and synthetic fibers stays dry and provides just the right cushioning.', N'Combinaison de fibres naturelles et synthétiques ; reste sèche et offre le confort nécessaire.', N'混合使用天然纤维和合成纤维，确保干燥并提供恰到好处的减震功能。', N'تركيبة من الفيبر الطبيعي والصناعي تظل محتفظة بجفافها وتعمل كوسائد ملائمة.', N'שילוב של סיבים טבעיים וסינטטיים נשאר יבש ומספק בדיוק את הריפוד הנכון.', N'การผสมผสานไฟเบอร์จากธรรมชาติและสังเคราะห์ แห้งสนิทและให้การรองรับที่เหมาะสม', N'Die Kombination aus natürlichen und synthetischen Fasern bleibt trocken und bietet genau die richtige Federung.', N'天然および合成繊維の組み合わせにより、湿気を防ぎ、適切な緩衝材を提供します。', N'Doğal ve sentetik fiber karışımı kuru kalır ve tam istenen yumuşaklığı sağlar.', CAST(N'2021-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2021-12-28T00:00:00.0000000' AS DateTime2), NULL)
