INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (481, N'SO-R809-M', 23, NULL, NULL, N'Racing Socks, M', N'Calcetines para carreras, M', N'Chaussettes de course, taille M', CAST(3.360000 AS Decimal(34, 6)), 1, N'White', 4, 3, CAST(8.990000 AS Decimal(34, 6)), N'M', N'M', NULL, 0, N'R ', CAST(5.390000 AS Decimal(34, 6)), NULL, N'U ', N'Racing Socks', N'Thin, lightweight and durable with cuffs that stay up.', N'Fin, léger et résistant avec des poignets qui restent en place.', N'贴身设计，轻便耐穿，带有紧口袖边。', N'رفيعة وخفيفة الوزن وشديدة التحمل ذات أكمام تظل ثابتة.', N'דק, קל-משקל ועמיד, עם חפתים שנותרים מורמים.', N'บาง น้ำหนักเบา และทนทาน พร้อมส่วนพับที่ไม่หลุด', N'"Dünn, leicht und robust mit Bündchen, die nicht verrutschen."', N'上部のカフスにより、薄くて軽量で耐久性があります。', N'"İnce, hafif ve dayanıklı kelepçeler."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
