INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (95, N'LI-3800', NULL, NULL, NULL, N'Internal Lock Washer 7', NULL, NULL, NULL, 0, N'NA', 1000, 750, NULL, NULL, N'NA', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, CAST(N'2021-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (446, N'PA-T100', 35, NULL, NULL, N'Touring-Panniers, Large', N'Cesta de paseo, grande', N'Sacoches de vélo de randonnée, grande capacité', CAST(51.560000 AS Decimal(34, 6)), 1, N'Grey', 4, 3, CAST(125.000000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'T ', CAST(75.000000 AS Decimal(34, 6)), NULL, NULL, N'Touring-Panniers', N'Durable, water-proof nylon construction with easy access. Large enough for weekend trips.', N'Fabrication en nylon résistant étanche d''accès facile. Suffisamment grand pour les randonnées du week-end.', N'易于拿取的耐用防水型尼龙结构。容量尽可满足周末旅行所需。', N'تركيبة نيلون شديدة التحمل مضادة للماء يمكن الوصول إليها بسهولة. واسعة بدرجة كافية لرحلات عطلة نهاية الأسبوع.', N'מבנה ניילון יציב ועמיד למים עם גישה קלה. גדול מספיק למסעות סופשבוע.', N'ทนทาน ทำจากไนลอนกันน้ำ ใช้งานง่าย  มีขนาดใหญ่พอสำหรับการเดินทางในช่วงสุดสัปดาห์', N'"Robustes, wasserfestes Nylon und einfacher Zugang. Groß genug für Wochenendfahrten."', N'耐久性と防水性に優れた使いやすいナイロン製。週末旅行に最適です。', N'"Kolay erişilebilen sağlam, su geçirmez naylon. Hafta sonu yolculukları için yeterince geniş."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (548, N'PD-T852', 13, NULL, NULL, N'Touring Pedal', N'Pedal de paseo', N'Pédale de vélo de randonnée', CAST(35.960000 AS Decimal(34, 6)), 1, N'Silver/Black', 500, 375, CAST(80.990000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'T ', CAST(48.590000 AS Decimal(34, 6)), NULL, NULL, N'Touring Pedal', N'A stable pedal for all-day riding.', N'Pédale stable pour longs trajets.', N'踏板稳固，可供全天候骑乘。', N'دواسة ثابتة ومتوازنة للقيادة طوال اليوم.', N'דוושה יציבה המתאימה לרכיבה לאורך כל היום.', N'คันถีบที่มั่นคง สำหรับการขี่เป็นเวลานาน', N'Ein stabiles Tretwerk für Fahrvergnügen den ganzen Tag.', N'長時間走行をサポートする安定したペダル。', N'Tüm gün sürüş için sağlam pedal.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
