INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (535, N'TI-M267', 37, NULL, NULL, N'LL Mountain Tire', N'Cubierta de montaña GB', N'Pneu de VTT LL', CAST(9.350000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(24.990000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'M ', CAST(14.990000 AS Decimal(34, 6)), N'L ', NULL, N'LL Mountain Tire', N'Comparible traction, less expensive wire bead casing.', N'Traction comparable aux modèles haut de gamme, gomme de pneu moins chère.', N'钢丝撑轮圈外胎的价格便宜，牵引力却可与高档车型相媲美。', N'قوة جر تضاهي أحدث الطرازات، غطاء حافة بارزة مطاطي منخفض الثمن.', N'אחיזת כביש נוחה בדומה לדגמים היוקרתיים, יציקת תילי צמיג יקרה פחות.', N'แรงยึดเกาะเทียบชั้นกับรุ่นระดับสูง ใช้โครงไวร์บีดราคาประหยัด', N'"Vergleichbare Beschleunigung, günstigerer Mantel."', N'優れたトラクション、低価格ワイヤ ビード ケーシング。', N'"Benzer yol tutuşu, daha ucuz tel başları."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (536, N'TI-M602', 37, NULL, NULL, N'ML Mountain Tire', N'Cubierta de montaña GM', N'Pneu de VTT ML', CAST(11.220000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(29.990000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'M ', CAST(17.990000 AS Decimal(34, 6)), N'M ', NULL, N'ML Mountain Tire', N'Great traction, high-density rubber.', N'Grande traction, caoutchouc haute densité.', N'出色的牵引力、高密度的橡皮。', N'قوة جر كبيرة، مطاط عالي الكثافة.', N'אחיזת כביש מעולה, גומי בצפיפות גבוהה.', N'แรงยึดเกาะที่เหนือกว่า ด้วยยางความหนาแน่นสูง', N'"Hohe Beschleunigung, Gummi mit hoher Dichte."', N'優れたトラクション、高密度ラバー。', N'"Çok iyi yol tutuşu, yüksek yoğunluklu lastik."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (404, N'HB-R504', 4, NULL, NULL, N'LL Road Handlebars', N'Manillar de carretera GB', N'Poignées de vélo de route LL', CAST(19.780000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(44.540000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'R ', CAST(26.720000 AS Decimal(34, 6)), N'L ', NULL, N'LL Road Handlebars', N'Unique shape provides easier reach to the levers.', N'Forme très réussie destinée à faciliter l''accès aux leviers.', N'独特的外形设计使得刹车把更易使用。', N'شكل فريد يوفر وصولاً أسهل إلى تروس التحكم في السرعة.', N'צורה ייחודית מספקת גישה קלה יותר לידיות ההילוכים.', N'รูปร่างที่เป็นเอกลักษณ์ ช่วยให้ใช้คานบันไดได้สะดวก', N'Einzigartige Form für komfortablere Bedienung der Schalthebel.', N'レバーに手が届きやすいユニークな形状。', N'Eşsiz biçimi kollara daha kolay erişim sağlar.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (406, N'HB-R720', 4, NULL, NULL, N'ML Road Handlebars', N'Manillar de carretera GM', N'Poignées de vélo de route ML', CAST(27.490000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(61.920000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'R ', CAST(37.150000 AS Decimal(34, 6)), N'M ', NULL, N'ML Road Handlebars', N'Anatomically shaped aluminum tube bar will suit all riders.', N'Barre d''appui avec tube en aluminium ergonomique pour répondre aux besoins de tous les cyclistes.', N'符合人体解剖学的铝制车把适用于所有骑乘者。', N'قضيب قيادة أنبوبي الشكل مصنوع من الألومنيوم ومشكّل بطريقة تتكيف مع بنية الراكب الجسمية ويناسب جميع الرّكاب.', N'צינור אלומיניום לידית המעוצבת בצורה אנטומית שתתאים לכל רוכב.', N'คานอลูมิเนียมที่ออกแบบตามหลักสรีรศาสตร์ เหมาะสำหรับนักปั่นทุกคน', N'Die anatomisch geformte Rohrstange ist für jeden Fahrer geeignet.', N'アナトミック形状のアルミニウム チューブ バーで、どのような乗り手にも適合します。', N'Anatomik biçimli alüminyum boru tüm sürücüler için uygundur.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (408, N'HB-R956', 4, NULL, NULL, N'HL Road Handlebars', N'Manillar de carretera GA', N'Poignées de vélo de route HL', CAST(53.400000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(120.270000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'R ', CAST(72.160000 AS Decimal(34, 6)), N'H ', NULL, N'HL Road Handlebars', N'Designed for racers; high-end anatomically shaped bar from aluminum alloy.', N'Conçu pour la compétition ; barre d''appui ergonomique haut de gamme en alliage d''aluminium.', N'专为竞赛者设计；高档且符合人体解剖学的铝合金车把。', N'أحدث قضيب قيادة مشكّل بطريقة تتكيف مع بنية الراكب الجسمية وهو مصنوع من سبيكة ألومنيوم، ومصمم للمتسابقين.', N'עיצוב המיוחד למתחרים; ידית אנטומית המעוצבת בצורה איכותית מסגסוגת אלומיניום.', N'คันบังคับชั้นเยี่ยม ได้รับการออกแบบตามหลักสรีรศาสตร์สำหรับนักแข่ง ทำจากอลูมิเนียมอัลลอยด์', N'Konzipiert für Rennfahrer; anatomisch geformte Stange aus Aluminiumlegierung.', N'レーサー用に設計された、高性能なアナトミック形状のアルミニウム合金バー。', N'Yarışçılar için tasarlanmış alüminyum alaşımı anatomik biçimli boru.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
