INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (521, N'SE-T312', 15, NULL, NULL, N'LL Touring Seat/Saddle', N'Sillín/asiento de paseo GB', N'Selle de vélo de randonnée LL', CAST(12.040000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(27.120000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'T ', CAST(16.270000 AS Decimal(34, 6)), N'L ', NULL, N'LL Touring Seat/Saddle', N'Comfortable, ergonomically shaped gel saddle.', N'Selle confortable et ergonomique profilée avec couvre-selle en gel.', N'舒适且符合人体工程学的含凝胶车座。', N'مقعد جيلاتيني مصمم بشكل يتناسب مع حركة الجسم.', N'מושב ג''ל נוח בעל עיצוב ארגונומי.', N'เบาะนั่งบรรจุเจล นุ่มสบาย มีรูปทรงตามหลักสรีรศาสตร์', N'Komfortabler Gelsattel mit ergonomischer Form.', N'快適なエルゴノミック形状のジェル製サドル。', N'"Konforlu, ergonomik biçimli jel sele."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (522, N'SE-T762', 15, NULL, NULL, N'ML Touring Seat/Saddle', N'Sillín/asiento de paseo GM', N'Selle de vélo de randonnée ML', CAST(17.380000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(39.140000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'T ', CAST(23.480000 AS Decimal(34, 6)), N'M ', NULL, N'ML Touring Seat/Saddle', N'New design relieves pressure for long rides.', N'Nouvelle conception pour éviter la fatigue lors des longues randonnées.', N'新型设计可缓解长时间骑乘的压力。', N'تصميم جديد لتخفيف الضغط عند القيادة لفترات طويلة.', N'עיצוב חדש להקלת לחץ ברכיבות ארוכות.', N'ออกแบบใหม่เพื่อบรรเทาแรงกดสำหรับการขับขี่ระยะไกล', N'Neues Design bietet Komfort auch auf langen Strecken.', N'ロング ライドのストレスを軽減する新デザイン。', N'Yeni tasarım uzun sürüşlerde basıncı azaltır.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (523, N'SE-T924', 15, NULL, NULL, N'HL Touring Seat/Saddle', N'Sillín/asiento de paseo GA', N'Selle de vélo de randonnée HL', CAST(23.370000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(52.640000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'T ', CAST(31.580000 AS Decimal(34, 6)), N'H ', NULL, N'HL Touring Seat/Saddle', N'Cut-out shell for a more comfortable ride.', N'Cadre profilé pour améliorer le confort.', N'精致的车架，令您骑乘更舒适。', N'هيكل خارجي تم تصميمه لتوفير مزيد من الراحة أثناء القيادة.', N'מעטפת קעורה לרכיבה נוחה יותר.', N'เปลือกพิเศษสำหรับการขับขี่ที่แสนสบาย', N'Ausgeschnittene Form für komfortableres Fahren.', N'より快適な乗り心地のためのカット アウト シェル。', N'Daha konforlu bir sürüş için özel sele kaplaması.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (553, N'HB-T721', 4, NULL, NULL, N'LL Touring Handlebars', N'Manillar de paseo GB', N'Poignées de vélo de randonnée LL', CAST(20.460000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(46.090000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'T ', CAST(27.650000 AS Decimal(34, 6)), N'L ', NULL, N'LL Touring Handlebars', N'Unique shape reduces fatigue for entry level riders.', N'Forme très réussie destinée à diminuer la fatigue des cyclistes occasionnels.', N'独特的外形设计有助于减轻入门级骑乘者的疲劳。', N'شكل فريد يقلل عناء القيادة على الركاب المبتدئين.', N'צורה ייחודית המפחיתה מעייפות הרוכב המתחיל.', N'รูปร่างที่เป็นเอกลักษณ์ช่วยลดความล้าสำหรับนักปั่นระดับเริ่มต้น', N'Mehr Komfort für Einsteiger durch einzigartige Form.', N'エントリー レベルのライダーにも疲労を感じさせないユニークな形状。', N'"Eşsiz biçimi, başlangıç seviyesindeki sürücülerde yorgunluğunu azaltır."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (554, N'HB-T928', 4, NULL, NULL, N'HL Touring Handlebars', N'Manillar de paseo GA', N'Poignées de vélo de randonnée HL', CAST(40.660000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(91.570000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'T ', CAST(54.940000 AS Decimal(34, 6)), N'H ', NULL, N'HL Touring Handlebars', N'A light yet stiff aluminum bar for long distance riding.', N'Barre d''appui en aluminium légère et solide pour les longues randonnées.', N'轻且坚固的铝制车把适用于长途骑乘。', N'قضيب قيادة مصنوع من الألومنيوم خفيف الوزن ولكنه قوي يتحمل القيادة لمسافات طويلة.', N'ידית אלומיניום קלה אך עם זאת קשיחה לרכיבה למרחקים ארוכים.', N'คันบังคับอลูมิเนียมแข็งแกร่ง เบา เหมาะสำหรับการขี่ระยะไกล', N'Leichtes und stabiles Aluminium für Langstrecken.', N'長距離ライディングに対応する軽量かつ高剛性のアルミニウム バー。', N'Uzun mesafe sürüş için hafif ancak sert alüminyum boru.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (478, N'BC-M005', 28, NULL, NULL, N'Mountain Bottle Cage', N'Portabotellas de montaña', N'Porte-bidon de VTT', CAST(3.740000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(9.990000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'M ', CAST(5.990000 AS Decimal(34, 6)), NULL, NULL, N'Mountain Bottle Cage', N'Tough aluminum cage holds bottle securly on tough terrain.', N'Porte-bidon en aluminium robuste qui maintient le bidon sur les terrains accidentés.', N'结实的铝壳可在任何环境下保持瓶子稳固。', N'هيكل قفصي من الألومنيوم يُثبت الزجاجة بإحكام أثناء القيادة على الأراضي الوعرة.', N'כלוב אלומיניום חזק שומר על הבקבוק בשטח קשה.', N'โครงอลูมิเนียมแข็งแกร่ง สำหรับใส่ขวดน้ำในเส้นทางวิบาก', N'Robuster Aluminiumrahmen hält die Flasche sicher auf schwierigem Gelände.', N'走行の困難な地形でもボトルをしっかりホールドする頑丈なアルミニウム ケージ。', N'Sağlam alüminyum kafes şişeyi zorlu yol koşullarında sıkıca tutar.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
