INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (196, N'SD-2342', NULL, NULL, NULL, N'LL Spindle/Axle', NULL, NULL, NULL, 0, N'NA', 500, 375, NULL, NULL, N'NA', NULL, 0, NULL, NULL, N'L ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, CAST(N'2021-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (479, N'BC-R205', 28, NULL, NULL, N'Road Bottle Cage', N'Portabotellas de carretera', N'Porte-bidon de vélo de route', CAST(3.360000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(8.990000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'R ', CAST(5.390000 AS Decimal(34, 6)), NULL, NULL, N'Road Bottle Cage', N'Aluminum cage is lighter than our mountain version; perfect for long distance trips.', N'Le porte-bidon en aluminium est plus léger que la version VTT ; idéal pour les longues randonnées.', N'铝制外胎比山地车胎更轻盈；是长途旅行的完美伴侣。', N'هيكل قفصي من الألومنيوم أخف من مثيله في طرازنا المخصص للقيادة في الجبال، وهو مثالي في الرحلات ذات المسافات الطويلة.', N'כלוב האלומיניום קל יותר מאשר הגירסה ההררית שלנו; מושלם עבור רכיבה למרחקים ארוכים.', N'โครงอลูมิเนียมมีน้ำหนักเบากว่ารุ่นภูเขา เหมาะสำหรับการเดินทางระยะไกล', N'Aluminiumrahmen ist leichter als unsere Mountain-Version; perfekt für Langstrecken.', N'アルミニウム ケージは、当社のマウンテン バージョンより軽量で、ツーリングに最適です。', N'Alüminyum kafes dağ modelimizdekinden daha hafiftir ve uzun mesafeli yolculuklar için idealdir.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (484, N'CL-9009', 29, NULL, NULL, N'Bike Wash - Dissolver', N'Lavado de bicicletas: disolvente', N'Entretien du vélo - dissolvant', CAST(2.970000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(7.950000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'S ', CAST(4.770000 AS Decimal(34, 6)), NULL, NULL, N'Bike Wash', N'Washes off the toughest road grime; dissolves grease, environmentally safe. 1-liter bottle.', N'Nettoie les saletés ; dissout la graisse. Protège l''environnement. Bouteille d''1 litre.', N'可洗去最顽固的污垢；可溶解油脂，利于环保。一升瓶装。', N'يمكنها إزالة أصعب أوساخ الطريق، وإذابة المواد الزيتية، كما أنها آمنة بيئيًا. زجاجة بسعة لتر واحد.', N'לשטיפת לכלוך הנאסף בדרכים קשות; ממס שומנים, בטוח לסביבה. בקבוק של 1 ליטר.', N'ทำความสะอาดสิ่งสกปรกที่ฝังแน่น ละลายจาระบี และไม่เป็นอันตรายต่อสิ่งแวดล้อม  ขวดบรรจุ 1 ลิตร', N'Entfernt den hartnäckigsten Schmutz und Fett; umweltfreundlich. 1-Liter-Flasche.', N'落ちにくい汚れを落とし、油を分解し、環境にも安全な 1 リットル入りボトル。', N'"En katı yol kirini yıkar, yağı akıtır, çevre dostudur. 1-litrelik şişede."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (485, N'FE-6654', 30, NULL, NULL, N'Fender Set - Mountain', N'Conjunto de guardabarros: montaña', N'Jeu de garde-boue - VTT', CAST(8.220000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(21.980000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'M ', CAST(13.190000 AS Decimal(34, 6)), NULL, NULL, N'Fender Set - Mountain', N'Clip-on fenders fit most mountain bikes.', N'Garde-boue adapté à la plupart des VTT.', N'卡扣式挡泥板适合大多数山地车。', N'رفارف مثبتة بمشابك تلائم معظم الدراجات المخصصة للقيادة في الجبال.', N'פגושים מתחברים המתאימים לרוב האופנים לרכיבה הררית.', N'แผ่นป้องกันแบบคลิปออน สำหรับจักรยานภูเขาทุกรุ่น', N'Schutzbleche zum Aufstecken passen auf fast alle Mountainbikes.', N'クリップオン式フェンダーは、ほとんどのマウンテン バイクに適合します。', N'Klipsli çamurluklar çoğu dağ bisikletine uyar.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (486, N'ST-1401', 27, NULL, NULL, N'All-Purpose Bike Stand', N'Soporte multiusos para bicicletas', N'Range-vélo pour tous modèles', CAST(59.470000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(159.000000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'M ', CAST(95.400000 AS Decimal(34, 6)), NULL, NULL, N'All-Purpose Bike Stand', N'Perfect all-purpose bike stand for working on your bike at home. Quick-adjusting clamps and steel construction.', N'Support de type home trainer idéal pour vous entraîner en intérieur (pour tous les modèles de vélo). Fixations rapides, fabrication en acier.', N'完美设计的全能型自行车支架，适用于在家中立地骑乘。钢结构，具有快速可调的固定夹。', N'حامل دراجة ممتاز متعدد الأغراض يلائم صيانة دراجتك بالمنزل. قوامط سريعة الضبط وتركيبة فولاذية.', N'מעמד רב-תכליתי לאופניים המיועד לטיפולי אופניים הנערכים בבית. כליבות להתאמה מהירה ומבנה פלדה.', N'ขาตั้งจักรยานอเนกประสงค์สำหรับจักรยานคันโปรดของคุณที่บ้าน  ที่ยึดปรับสะดวก และโครงสร้างเหล็กกล้า', N'"Optimaler Allzweck-Fahrradständer für die Wartung des Rads zu Hause. Leicht anpassbare Klemmen, Stahlkonstruktion."', N'自宅での作業にも完璧な多目的スタンドで、迅速な調整が可能なクランプと鋼構造を備えています。', N'Evinizde bisikletiniz üzerinde çalışmanız için mükemmel çok amaçlı bisiklet standı. Hızlı ayarlanabilen klempler ve çelik konstrüksiyon.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (391, N'FK-1639', 10, NULL, NULL, N'LL Fork', N'Horquilla GB', N'Fourche LL', CAST(65.810000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(148.220000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, NULL, CAST(88.930000 AS Decimal(34, 6)), N'L ', NULL, N'LL Fork', N'Stout design absorbs shock and offers more precise steering.', N'Conception robuste permettant d''absorber les chocs et d''offrir une conduite plus précise.', N'结实的设计不仅避震还可实现更精确的操控。', N'تصميم قوي يمتص الصدمات ويوفر قيادة أكثر دقة.', N'עיצוב חזק סופג זעזועים ומציע היגוי מדויק יותר.', N'การออกแบบที่มั่นคง รับแรงกระแทกและให้การควบคุมที่แม่นยำ', N'Das robuste Design dämpft Stöße und ermöglicht eine präzisere Steuerung.', N'頑丈なデザインにより衝撃が吸収され、より正確なハンドル操作が可能です。', N'Şoku emen ve daha hassas yönlendirilebilen güçlü tasarım.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (392, N'FK-5136', 10, NULL, NULL, N'ML Fork', N'Horquilla GM', N'Fourche ML', CAST(77.920000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(175.490000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, NULL, CAST(105.290000 AS Decimal(34, 6)), N'M ', NULL, N'ML Fork', N'Composite road fork with an aluminum steerer tube.', N'Fourche composite pour route avec tube de direction en aluminium.', N'具有铝制前叉竖管的组合式公路车前叉。', N'شوكة طريق ماسكة للعجلة الأمامية مركبة ذات عمود توجيه مصنوع من الألومنيوم.', N'מזלג כביש מורכב עם צינור עמוד היגוי מאלומיניום.', N'ตะเกียบคู่โลหะผสม พร้อมท่อคันบังคับอลูมิเนียม', N'Gabel für die Straße mit Aluminium-Lenkerrohr.', N'アルミニウム製ステアリング チューブを備えたコンポジット ロード フォーク。', N'Alüminyum gidon boğazlı kompozit maşa.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (393, N'FK-9939', 10, NULL, NULL, N'HL Fork', N'Horquilla GA', N'Fourche HL', CAST(101.890000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(229.490000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, NULL, CAST(137.690000 AS Decimal(34, 6)), N'H ', NULL, N'HL Fork', N'High-performance carbon road fork with curved legs.', N'Fourche pour route en carbone hautes performances avec bras incurvés.', N'具有弯管的高性能碳纤维公路车前叉。', N'شوكة طريق ماسكة للعجلة الأمامية من الكربون عالية الأداء ذات شعبتين مقوسين.', N'מזלג כביש מפחמן עם רגליים מוטות לביצועים גבוהים.', N'ตะเกียบคู่คาร์บอนประสิทธิภาพสูง พร้อมขาโค้ง', N'Hochwertige Carbon-Gabel mit geschwungenen Seiten.', N'湾曲したレッグを持つ高性能のカーボン ロード フォーク。', N'Yüksek performanslı eğik ayaklı karbon maşa.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (394, N'HS-0296', 11, NULL, NULL, N'LL Headset', N'Dirección GB', N'Jeu de direction LL', CAST(15.180000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(34.200000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, NULL, CAST(20.520000 AS Decimal(34, 6)), N'L ', NULL, N'LL Headset', N'Threadless headset provides quality at an economical price.', N'Jeu de direction de qualité sans filetage à un prix abordable.', N'无螺纹的车头碗组不仅确保质量而且经济实惠。', N'توفر الوصلة غير الملولبة بين الشوكة الماسكة للعجلة الأمامية وبقية هيكل الدراجة الجودة المطلوبة وبسعر اقتصادي.', N'טבעת נטולת תבריג מספקת איכות במחיר חסכוני.', N'ชุดประกอบส่วนหัวไม่มีเกลียว คุณภาพสูงในราคาประหยัด', N'Hochwertiger Lenkkopf zu einem guten Preis.', N'スレッドレスのヘッドセットは、手ごろな価格で高品質を提供します。', N'Furş takımı kaliteyi ekonomik bir fiyata sunar.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (395, N'HS-2451', 11, NULL, NULL, N'ML Headset', N'Dirección GM', N'Jeu de direction ML', CAST(45.420000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(102.290000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, NULL, CAST(61.370000 AS Decimal(34, 6)), N'M ', NULL, N'ML Headset', N'Sealed cartridge keeps dirt out.', N'Boîtier de protection hermétique.', N'密封的缓冲油管，纤尘不染。', N'تمنع الخرطوشة محكمة الإغلاق الأوساخ من الدخول.', N'קסטה אטומה שומרת מפני לכלוך.', N'กล่องผนึกสนิทป้องกันฝุ่นละออง', N'Versiegeltes Ventil vermeidet das Eindringen von Schmutz.', N'密閉されたカートリッジが埃を防ぎます。', N'Mühürlü kartuş kirden korur.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (396, N'HS-3479', 11, NULL, NULL, N'HL Headset', N'Dirección GA', N'Jeu de direction HL', CAST(55.380000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(124.730000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, NULL, CAST(74.840000 AS Decimal(34, 6)), N'H ', NULL, N'HL Headset', N'High-quality 1" threadless headset with a grease port for quick lubrication.', N'Jeu de direction sans filetage 2,54 cm de grande qualité avec un dispositif de lubrification rapide.', N'高质量的一英寸无螺纹车头碗组具有油口，可确保快速润滑。', N'وصلة غير ملولبة بين الشوكة الماسكة للعجلة الأمامية وبقية هيكل الدراجة بمساحة 1 بوصة ذات جودة عالية مزودة بمنفذ تشحيم لإجراء التشحيم بشكل سريع.', N'טבעת נטולת תבריג בקוטר 1 אינץ'' עם פתח סיכה לסיכה מהירה.', N'ชุดประกอบส่วนหัวไม่มีเกลียวคุณภาพสูง ขนาด 1 นิ้วพร้อมช่องจาระบีสำหรับการหล่อลื่นอย่างรวดเร็ว', N'Hochwertiger Lenkkopf 1 Zoll mit Schmierfettdurchlauf.', N'迅速な注油のための注油ポートを備えた高品質の 1 インチ スレッドレス ヘッドセット。', N'"Yüksek kaliteli 1"" furş takımı, hızlı yağlama için yağ kapaklı."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (403, N'HB-R504', 4, NULL, NULL, N'LL Road Handlebars', N'Manillar de carretera GB', N'Poignées de vélo de route LL', CAST(17.980000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(40.490000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'R ', CAST(24.290000 AS Decimal(34, 6)), N'L ', NULL, N'LL Road Handlebars', N'Unique shape provides easier reach to the levers.', N'Forme très réussie destinée à faciliter l''accès aux leviers.', N'独特的外形设计使得刹车把更易使用。', N'شكل فريد يوفر وصولاً أسهل إلى تروس التحكم في السرعة.', N'צורה ייחודית מספקת גישה קלה יותר לידיות ההילוכים.', N'รูปร่างที่เป็นเอกลักษณ์ ช่วยให้ใช้คานบันไดได้สะดวก', N'Einzigartige Form für komfortablere Bedienung der Schalthebel.', N'レバーに手が届きやすいユニークな形状。', N'Eşsiz biçimi kollara daha kolay erişim sağlar.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
