INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (405, N'HB-R720', 4, NULL, NULL, N'ML Road Handlebars', N'Manillar de carretera GM', N'Poignées de vélo de route ML', CAST(24.990000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(56.290000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'R ', CAST(33.770000 AS Decimal(34, 6)), N'M ', NULL, N'ML Road Handlebars', N'Anatomically shaped aluminum tube bar will suit all riders.', N'Barre d''appui avec tube en aluminium ergonomique pour répondre aux besoins de tous les cyclistes.', N'符合人体解剖学的铝制车把适用于所有骑乘者。', N'قضيب قيادة أنبوبي الشكل مصنوع من الألومنيوم ومشكّل بطريقة تتكيف مع بنية الراكب الجسمية ويناسب جميع الرّكاب.', N'צינור אלומיניום לידית המעוצבת בצורה אנטומית שתתאים לכל רוכב.', N'คานอลูมิเนียมที่ออกแบบตามหลักสรีรศาสตร์ เหมาะสำหรับนักปั่นทุกคน', N'Die anatomisch geformte Rohrstange ist für jeden Fahrer geeignet.', N'アナトミック形状のアルミニウム チューブ バーで、どのような乗り手にも適合します。', N'Anatomik biçimli alüminyum boru tüm sürücüler için uygundur.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (407, N'HB-R956', 4, NULL, NULL, N'HL Road Handlebars', N'Manillar de carretera GA', N'Poignées de vélo de route HL', CAST(48.550000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(109.340000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'R ', CAST(65.600000 AS Decimal(34, 6)), N'H ', NULL, N'HL Road Handlebars', N'Designed for racers; high-end anatomically shaped bar from aluminum alloy.', N'Conçu pour la compétition ; barre d''appui ergonomique haut de gamme en alliage d''aluminium.', N'专为竞赛者设计；高档且符合人体解剖学的铝合金车把。', N'أحدث قضيب قيادة مشكّل بطريقة تتكيف مع بنية الراكب الجسمية وهو مصنوع من سبيكة ألومنيوم، ومصمم للمتسابقين.', N'עיצוב המיוחד למתחרים; ידית אנטומית המעוצבת בצורה איכותית מסגסוגת אלומיניום.', N'คันบังคับชั้นเยี่ยม ได้รับการออกแบบตามหลักสรีรศาสตร์สำหรับนักแข่ง ทำจากอลูมิเนียมอัลลอยด์', N'Konzipiert für Rennfahrer; anatomisch geformte Stange aus Aluminiumlegierung.', N'レーサー用に設計された、高性能なアナトミック形状のアルミニウム合金バー。', N'Yarışçılar için tasarlanmış alüminyum alaşımı anatomik biçimli boru.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (447, N'LO-C100', 34, NULL, NULL, N'Cable Lock', N'Cable antirrobo', N'Antivol câble', CAST(10.310000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(25.000000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'S ', CAST(15.000000 AS Decimal(34, 6)), NULL, NULL, N'Cable Lock', N'Wraps to fit front and rear tires, carrier and 2 keys included.', N'S''enroule pour s''adapter aux pneus avant et arrière, sac et deux clés fournis.', N'所携装备可置于前面和后面，包括行李架和两把钥匙。', N'أغلفة تناسب الإطارين الأمامي والخلفي، وتشمل حاملاً ومفتاحين.', N'נכרך להתאמה לצמיג קדמי ואחורי, מנשא ושני מפתחות כלולים.', N'ที่หุ้มยางสำหรับยางหน้าหรือยางหลัง พร้อมที่ใส่และกุญแจสองดอก', N'"Passt für Vorder- und Hinterrad, mit Halterung und 2 Schlüsseln."', N'フロント タイヤとリア タイヤを収納でき、キャリアと鍵 2 つが付属しています。', N'"Ön ve arka tekerleklere uyacak şekilde sarılabilir, taşıyıcı ve iki anahtar dahildir."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (449, N'PU-M044', 36, NULL, NULL, N'Mountain Pump', N'Bomba de montaña', N'Pompe de VTT', CAST(10.310000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(24.990000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'M ', CAST(14.990000 AS Decimal(34, 6)), NULL, NULL, N'Mountain Pump', N'Simple and light-weight. Emergency patches stored in handle.', N'Simple et léger. Rustines de secours rangées dans la poignée.', N'简单轻便。应急补片存放在手把中。', N'بسيطة وخفيفة الوزن. رقع لصق للطوارئ مخزنة في قضيب القيادة.', N'פשוט וקל-משקל. טלאי חירום מאוחסנים בידית.', N'เรียบง่าย น้ำหนักเบา  ที่ปะยางฉุกเฉินเก็บได้ในคันบังคับ', N'Einfach und leicht. Flickzeug im Griff.', N'シンプルで軽量。緊急用パッチがハンドルに格納されています。', N'Kolay ve hafif. Acil durum yamaları kolda saklanır.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
