INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (448, N'PU-0452', 36, NULL, NULL, N'Minipump', NULL, NULL, CAST(8.250000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(19.990000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'S ', CAST(11.990000 AS Decimal(34, 6)), NULL, NULL, N'Minipump', N'Designed for convenience. Fits in your pocket. Aluminum barrel. 160psi rated.', N'Très pratique. Tient dans la poche. Corps en aluminium. 11,2 bars.', N'专门设计，确保方便。可装在您的口袋里。铝制气筒。额定气压为 160psi。', N'مصممة لتوفير الراحة التامة. تلائم حجم الجيب. ماسورة من الألومنيوم. بمعدل رطل في البوصة المربعة.', N'עיצוב המיועד לנוחות. מתאים לכיס. מיכל אלומיניום. 160 psi נקובים.', N'ออกแบบเพื่อความสะดวก  ขนาดกะทัดรัด ใส่พอดีกระเป๋า  กระบอกอลูมิเนียม  ขนาด 160psi', N'Komfortables Design. Passt in Ihre Tasche. Aluminiumrohr. 11 Bar.', N'便利さを追求したデザインで、ポケットに入るアルミバレル (最大 160 psi)。 ', N'Rahatlık için tasarlandı. Cebinize sığar. Alüminyum varil. 160 psi basınç.', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (450, N'LT-T990', 33, NULL, NULL, N'Taillights - Battery-Powered', NULL, NULL, CAST(5.770000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(13.990000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'R ', CAST(8.390000 AS Decimal(34, 6)), NULL, NULL, N'Taillight', N'Affordable light for safe night riding - uses 3 AAA batteries', N'Éclairage peu onéreux pour la conduite de nuit - utilise 3 piles AAA.', N'价格适中的车灯，确保夜间骑乘安全 – 使用三节 AAA 电池', N'إضاءة ذات سعر منخفض للقيادة بشكل آمن ليلاً، تستخدم 3 بطاريات AAA.', N'תאורה במחיר סביר לרכיבה לילית בטוחה – פועלת באמצעות סוללת AAA', N'ไฟราคาประหยัดสำหรับการขับขี่ยามค่ำคืนที่ปลอดภัย - ใช้แบตเตอรี่ AAA 3 ก้อน', N'Kostengünstiges Licht für sicheres Fahren bei Nacht - mit 3 AAA-Batterien', N'安全な夜間走行をサポートする低価格のライト (単 4 電池を 3 つ使用)。', N'"Güvenli gece sürüşü için ekonomik far, 3 adet AAA pil kullanır"', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (477, N'WB-H098', 28, NULL, NULL, N'Water Bottle - 30 oz.', NULL, NULL, CAST(1.870000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(4.990000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'S ', CAST(2.990000 AS Decimal(34, 6)), NULL, NULL, N'Water Bottle', N'AWC logo water bottle - holds 30 oz; leak-proof.', N'Bidon d''eau avec le logo de l''équipe AWC - capacité 0,75 litre, entièrement étanche.', N'带有 AWC 徽标的水瓶容量为 30 盎司；防漏设计。', N'زجاجة مياه تحمل شعار AWC تستوعب 840 غرامًا من المياه، وهي مضادة للتسرب.', N'בקבוק מים מתוצרת AWC – מכיל 850 גרם; עמיד מפני נזילה.', N'ขวดน้ำติดโลโก้ AWC - บรรจุ 30 ออนซ์ พร้อมป้องกันการรั่วไหล', N'Wasserflasche mit AWC-Logo - 880 ml; auslaufsicher.', N'AWC ロゴ入りの水筒 - 容量 30 オンス、漏れ防止。', N'"AWC logolu matara - 0,9 litre; sızdırmaz."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (480, N'PK-7098', 37, NULL, NULL, N'Patch Kit/8 Patches', NULL, NULL, CAST(0.860000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(2.290000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'S ', CAST(1.370000 AS Decimal(34, 6)), NULL, NULL, N'Patch kit', N'Includes 8 different size patches, glue and sandpaper.', N'Comprend 8 rustines de tailles différentes, de la colle et du papier de verre.', N'包括八种不同尺寸的补片、胶水和砂纸。', N'تشمل 8 رقع لصق مختلفة الحجم، ومادة غروية لاصقة، وورق سنفرة.', N'כולל 8 טלאים בגדלים שונים, דבק ונייר זכוכית.', N'ประกอบด้วยแผ่นปะยาง 8 ขนาด กาว และกระดาษทราย', N'"Enthält Flicken in 8 verschiedenen Größen, Klebstoff und Sandpapier."', N'8 種類の異なるサイズのパッチ、糊、およびサンド ペーパーが含まれます。', N'"8 farklı boyda yama, yapışkan ve zımpara kağıdı  içerir."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (483, N'RA-H123', 26, NULL, NULL, N'Hitch Rack - 4-Bike', NULL, NULL, CAST(44.880000 AS Decimal(34, 6)), 1, N'NA', 4, 3, CAST(120.000000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'S ', CAST(72.000000 AS Decimal(34, 6)), NULL, NULL, N'Hitch Rack - 4-Bike', N'Carries 4 bikes securely; steel construction, fits 2" receiver hitch.', N'Porte-vélo sécurisé pour 4 vélos ; fabrication en acier ; adaptable sur attache-remorque.', N'可安全运载四辆自行车；钢结构；配有二英寸的固定装置。', N'يحمل 4 دراجات بشكل آمن، ذو بنية فولاذية، ويناسب عقدة تعليق بمساحة 2 بوصة.', N'נושא 4 זוגות אופניים בבטחה; מבנה פלדה; מתאים לרתמת מתלה של 2 אינץ''.', N'บรรทุกรถจักรยาน 4 คันอย่างปลอดภัย ด้วยโครงสร้างเหล็กกล้า ใช้กับขอเกี่ยวขนาด 2 นิ้ว', N'"Sicherer Transport von 4 Fahrrädern; Stahlkonstruktion, passt in 2-Zoll-Kupplung."', N'4 台の自転車を安全に積載、スチール構造、2 インチ レシーバ ヒッチ用。', N'"4 bisikleti güvenli bir şekilde taşır, çelik konstrüksiyon, 2'''' çekiye sabitlenebilir."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
