INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (517, N'SE-M940', 15, NULL, NULL, N'HL Mountain Seat/Saddle', NULL, NULL, CAST(23.370000 AS Decimal(34, 6)), 1, N'NA', 500, 375, CAST(52.640000 AS Decimal(34, 6)), NULL, N'NA', NULL, 1, N'M ', CAST(31.580000 AS Decimal(34, 6)), N'H ', NULL, N'HL Mountain Seat/Saddle 2', N'Anatomic design for a full-day of riding in comfort. Durable leather.', N'Conception ergonomique pour randonnée longue distance confortable. Cuir de qualité.', N'符合人体解剖学的设计确保全天候舒适骑乘。皮革材质持久耐用。', N'تصميم يتناسب مع بنية الراكب الجسمية لتوفير قيادة مريحة طوال اليوم. جلد شديد التحمل.', N'עיצוב אנטומי לרכיבה נוחה לאורך כל היום. עור עמיד.', N'ออกแบบตามหลักสรีรศาสตร์ สำหรับการขับขี่อย่างสบายตลอดทั้งวัน  ทำจากหนังที่ทนทาน', N'Anatomisches Design für komfortables Fahrvergnügen den ganzen Tag. Widerstandsfähiges Leder.', N'1 日中乗っても快適なアナトミック デザインで、耐久性のある皮製。', N'Tüm gün konforlu sürüş için anatomik tasarım. Dayanıklı deri.', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (223, N'CA-1098', 19, NULL, NULL, N'AWC Logo Cap', NULL, NULL, CAST(5.710000 AS Decimal(34, 6)), 1, N'Multi', 4, 3, CAST(8.640000 AS Decimal(34, 6)), NULL, N'NA', NULL, 0, N'S ', CAST(5.190000 AS Decimal(34, 6)), NULL, N'U ', N'Cycling Cap', N'Traditional style with a flip-up brim; one-size fits all.', N'Style classique avec une visière relevable ; taille unique.', N'经典式样，带有翻边；均码。', N'نمط تقليدي ذو حافة قابلة للانقلاب لأعلى، بحجم واحد يلائم الجميع.', N'סגנון מסורתי עם מצחייה מתרוממת; גודל אחד מתאים לכולם.', N'แบบดั้งเดิม พร้อมขอบพับ ใช้ได้กับทุกคน', N'"Traditionelles Design mit Klapprand, Einheitsgröße."', N'跳ね上げ式のつばを持つトラディショナルなスタイルで、フリーサイズです。', N'"Klasik stil, herkese uygun tek bir boyda."', CAST(N'2021-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2021-12-28T00:00:00.0000000' AS DateTime2), NULL)
