INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (459, N'SB-M891-S', 18, NULL, NULL, N'Men''s Bib-Shorts, S', NULL, NULL, CAST(37.120000 AS Decimal(34, 6)), 1, N'Multi', 4, 3, CAST(89.990000 AS Decimal(34, 6)), N'S', N'S', NULL, 0, N'S ', CAST(53.990000 AS Decimal(34, 6)), NULL, N'M ', N'Men''s Bib-Shorts', N'Designed for the AWC team with stay-put straps, moisture-control, chamois padding, and leg grippers.', N'Conçu pour l''équipe professionnelle AWC, à bretelles, contrôle de l''humidité, peau de chamois et bande anti-remontée.', N'专为 AWC 赛车队设计，配有固定扣带、湿度控制器、麂皮垫和腿夹。', N'مصممة لفريق AWC مع أشرطة ثابتة، وتحكم في الرطوبة، وحشو شمواة، وماسكات للرجلين.', N'מעוצב עבור הקבוצה של AWC עם רצועות הידוק, בקרת לחות, ריפוד מעור רך והידוק לרגליים.', N'ได้รับการออกแบบสำหรับทีม AWC พร้อมสายรัด ตัวควบคุมความชื้น บุชามัวส์ และที่รัดขา', N'"Konzipiert für das AWC-Team mit Gummizug, atmungsaktiv, Lederpolsterung, Beinabschluss ohne Verrutschen."', N'AWC チーム用に設計され、外れにくいストラップ、湿度調整機能、シャモア パッド、レッグ グリッパーを備えています。', N'"Yerinden oynamayan askıları, nem kontrolü, pedi ve bacak tutucularıyla AWC takımı için tasarlandı."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
