INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (462, N'GL-H102-S', 20, NULL, NULL, N'Half-Finger Gloves, S', NULL, NULL, CAST(9.710000 AS Decimal(34, 6)), 1, N'Black', 4, 3, CAST(23.550000 AS Decimal(34, 6)), N'S', N'S', NULL, 0, N'S ', CAST(14.130000 AS Decimal(34, 6)), NULL, N'U ', N'Half-Finger Gloves', N'Full padding, improved finger flex, durable palm, adjustable closure.', N'Entièrement rembourré, amélioration de la souplesse de mouvement des doigts, paume renforcée, fermeture réglable.', N'完全填充、手指活动更自如、手掌材质更耐用、大小可调。', N'قفاز يد ذو حشوة كاملة، وثنية أصابع محسنة، وغطاء قوي لراحة اليد، كما يمكن تعديل مكان إغلاقه.', N'ריפוד מלא, אפשרות כיפוף משופרת לאצבעות, עמידות באזור כף היד, סגירה ניתנת להתאמה.', N'บุเต็มทุกส่วน เพิ่มการยืดหยุ่นของนิ้ว แผ่นฝ่ามือทนทาน ที่รัดปรับได้', N'"Vollständig gepolstert, verbesserte Flexibilität für die Finger, robuster Ballenschutz, anpassbarer Verschluss."', N'フル パディング、改良された指部分の伸縮性、耐久性のある手のひら部分、調整可能なはめ口。', N'"Ful pedli, geliştirilmiş parmak esnekliği, dayanıklı avuç içi, ayarlanabilir kopça."', CAST(N'2022-07-01T00:00:00.0000000' AS DateTime2), CAST(N'2022-12-27T00:00:00.0000000' AS DateTime2), NULL)
