INSERT [dbo].[dimproduct] ([ProductKey], [ProductAlternateKey], [ProductSubcategoryKey], [WeightUnitMeasureCode], [SizeUnitMeasureCode], [EnglishProductName], [SpanishProductName], [FrenchProductName], [StandardCost], [FinishedGoodsFlag], [Color], [SafetyStockLevel], [ReorderPoint], [ListPrice], [Size], [SizeRange], [Weight], [DaysToManufacture], [ProductLine], [DealerPrice], [Class], [Style], [ModelName], [EnglishDescription], [FrenchDescription], [ChineseDescription], [ArabicDescription], [HebrewDescription], [ThaiDescription], [GermanDescription], [JapaneseDescription], [TurkishDescription], [StartDate], [EndDate], [Status]) VALUES (474, N'SH-W890-S', 22, NULL, NULL, N'Women''s Mountain Shorts, S', NULL, NULL, CAST(26.180000 AS Decimal(34, 6)), 1, N'Black', 4, 3, CAST(69.990000 AS Decimal(34, 6)), N'S', N'S', NULL, 0, N'M ', CAST(41.990000 AS Decimal(34, 6)), NULL, N'W ', N'Women''s Mountain Shorts', N'Heavy duty, abrasion-resistant shorts feature seamless, lycra inner shorts with anti-bacterial chamois for comfort.', N'Cuissards résistants à l''usure pour utilisation intensive, doublés à l''intérieur en Spandex, sans couture, peau de chamois anti-bactérie pour un meilleur confort.', N'高弹力、耐磨型运动短裤，无缝氨纶内衬带有抗菌麂皮，确保穿着舒适。', N'قمصان شديدة التحمل مقاومة للاحتكاكات تحتوي على قمصان داخلية أخرى خالية من الفتحات مصنوعة من قماش سباندكس ومبطنة بشمواة مضاد للبكتريا لتوفير الراحة.', N'מכנסיים קצרים לפעילות מאומצת, מונעי שפשוף מאופיינים בחלק פנימי מספנדקס נטול תפרים ועור רך אנטי-בקטריאלי לתוספת נוחות.', N'กางเกงขาสั้น ทนการขีดข่วน ทำจากเส้นใยสแปนเด็กซ์ไร้ตะเข็บ พร้อมด้วยชามัวส์ป้องกันแบคทีเรีย สวมสบาย', N'"Robuste, abnutzungsresistente Radlerhose mit nahtloser Innenhose aus Lycra mit antibakteriellem Gemsleder für höchsten Komfort."', N'丈夫で耐摩耗性に優れたショーツは、抗菌シャモアで快適さを追求するシームレス ライクラ インナー付き。', N'"Ağır işe ve aşınmaya dayanıklı şortlar, konfor için anti bakteriyel pedli dikişsiz likra astar şort."', CAST(N'2023-07-01T00:00:00.0000000' AS DateTime2), NULL, N'Current')
